-- ALWIN Laravel dump (MySQL 5.7+ / 8)
-- SAFETY: first install or backup restore only.
-- Do NOT import this into a live database that already has data.
-- This file DROPS tables, then recreates them.
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS=0;
SET SQL_MODE='NO_AUTO_VALUE_ON_ZERO';

DROP TABLE IF EXISTS `activity_logs`;
CREATE TABLE `activity_logs` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `user_id` BIGINT UNSIGNED,
  `action` VARCHAR(255) NOT NULL,
  `subject_type` VARCHAR(255),
  `subject_id` BIGINT UNSIGNED,
  `description` LONGTEXT,
  `properties` JSON,
  `ip_address` VARCHAR(255),
  `created_at` DATETIME,
  `updated_at` DATETIME,
  KEY `activity_logs_created_at_index` (`created_at`),
  KEY `activity_logs_subject_type_subject_id_index` (`subject_type`, `subject_id`),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `articles`;
CREATE TABLE `articles` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `title` VARCHAR(255) NOT NULL,
  `slug` VARCHAR(255) NOT NULL,
  `excerpt` TEXT,
  `body` LONGTEXT,
  `cover_path` VARCHAR(255),
  `cover_alt` VARCHAR(255),
  `author` VARCHAR(255),
  `published_at` DATETIME,
  `status` VARCHAR(255) NOT NULL DEFAULT 'published',
  `seo_title` VARCHAR(255),
  `seo_description` VARCHAR(255),
  `created_at` DATETIME,
  `updated_at` DATETIME,
  `deleted_at` DATETIME,
  `show_on_listing` TINYINT(1) NOT NULL DEFAULT 1,
  UNIQUE KEY `articles_slug_unique` (`slug`),
  KEY `articles_status_published_at_index` (`status`, `published_at`),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `cache`;
CREATE TABLE `cache` (
  `key` VARCHAR(255) NOT NULL,
  `value` LONGTEXT NOT NULL,
  `expiration` BIGINT UNSIGNED NOT NULL,
  KEY `cache_expiration_index` (`expiration`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `cache_locks`;
CREATE TABLE `cache_locks` (
  `key` VARCHAR(255) NOT NULL,
  `owner` VARCHAR(255) NOT NULL,
  `expiration` BIGINT UNSIGNED NOT NULL,
  KEY `cache_locks_expiration_index` (`expiration`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `contact_inquiries`;
CREATE TABLE `contact_inquiries` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `name` VARCHAR(255) NOT NULL,
  `phone` VARCHAR(255) NOT NULL,
  `email` VARCHAR(255),
  `subject` VARCHAR(255) NOT NULL DEFAULT 'callback',
  `message` TEXT,
  `source` VARCHAR(255) NOT NULL DEFAULT 'contact',
  `status` VARCHAR(255) NOT NULL DEFAULT 'new',
  `ip_address` VARCHAR(255),
  `created_at` DATETIME,
  `updated_at` DATETIME,
  KEY `contact_inquiries_status_created_at_index` (`status`, `created_at`),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `failed_jobs`;
CREATE TABLE `failed_jobs` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `uuid` VARCHAR(255) NOT NULL,
  `connection` TEXT NOT NULL,
  `queue` TEXT NOT NULL,
  `payload` LONGTEXT NOT NULL,
  `exception` LONGTEXT NOT NULL,
  `failed_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE KEY `failed_jobs_uuid_unique` (`uuid`),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `job_batches`;
CREATE TABLE `job_batches` (
  `id` VARCHAR(255) NOT NULL,
  `name` VARCHAR(255) NOT NULL,
  `total_jobs` BIGINT UNSIGNED NOT NULL,
  `pending_jobs` BIGINT UNSIGNED NOT NULL,
  `failed_jobs` BIGINT UNSIGNED NOT NULL,
  `failed_job_ids` TEXT NOT NULL,
  `options` TEXT,
  `cancelled_at` BIGINT UNSIGNED,
  `created_at` DATETIME NOT NULL,
  `finished_at` BIGINT UNSIGNED
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `jobs`;
CREATE TABLE `jobs` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `queue` VARCHAR(255) NOT NULL,
  `payload` LONGTEXT NOT NULL,
  `attempts` BIGINT UNSIGNED NOT NULL,
  `reserved_at` BIGINT UNSIGNED,
  `available_at` BIGINT UNSIGNED NOT NULL,
  `created_at` DATETIME NOT NULL,
  KEY `jobs_queue_index` (`queue`),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `media`;
CREATE TABLE `media` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `disk` VARCHAR(255) NOT NULL DEFAULT 'public',
  `path` VARCHAR(255) NOT NULL,
  `filename` VARCHAR(255) NOT NULL,
  `original_name` VARCHAR(255),
  `mime` VARCHAR(255),
  `size` BIGINT UNSIGNED NOT NULL DEFAULT 0,
  `kind` VARCHAR(255) NOT NULL DEFAULT 'image',
  `alt` VARCHAR(255),
  `width` BIGINT UNSIGNED,
  `height` BIGINT UNSIGNED,
  `uploaded_by` BIGINT UNSIGNED,
  `created_at` DATETIME,
  `updated_at` DATETIME,
  `deleted_at` DATETIME,
  KEY `media_kind_created_at_index` (`kind`, `created_at`),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `migrations`;
CREATE TABLE `migrations` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `migration` VARCHAR(255) NOT NULL,
  `batch` BIGINT UNSIGNED NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `navigation_items`;
CREATE TABLE `navigation_items` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `location` VARCHAR(255) NOT NULL DEFAULT 'header',
  `label` VARCHAR(255) NOT NULL,
  `url` VARCHAR(255) NOT NULL,
  `sort_order` BIGINT UNSIGNED NOT NULL DEFAULT 0,
  `is_active` TINYINT(1) NOT NULL DEFAULT 1,
  `created_at` DATETIME,
  `updated_at` DATETIME,
  KEY `navigation_items_location_sort_order_index` (`location`, `sort_order`),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `page_blocks`;
CREATE TABLE `page_blocks` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `page_id` BIGINT UNSIGNED NOT NULL,
  `key` VARCHAR(255) NOT NULL,
  `type` VARCHAR(255) NOT NULL DEFAULT 'text',
  `label` VARCHAR(255),
  `value` LONGTEXT,
  `sort_order` BIGINT UNSIGNED NOT NULL DEFAULT 0,
  `created_at` DATETIME,
  `updated_at` DATETIME,
  UNIQUE KEY `page_blocks_page_id_key_unique` (`page_id`, `key`),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `pages`;
CREATE TABLE `pages` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `key` VARCHAR(255) NOT NULL,
  `title` VARCHAR(255) NOT NULL,
  `path` VARCHAR(255),
  `seo_title` VARCHAR(255),
  `seo_description` VARCHAR(255),
  `created_at` DATETIME,
  `updated_at` DATETIME,
  UNIQUE KEY `pages_key_unique` (`key`),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `partners`;
CREATE TABLE `partners` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `name` VARCHAR(255) NOT NULL,
  `alt_text` VARCHAR(255),
  `image_id` BIGINT UNSIGNED,
  `url` VARCHAR(255),
  `sort_order` BIGINT UNSIGNED NOT NULL DEFAULT 0,
  `is_active` TINYINT(1) NOT NULL DEFAULT 1,
  `created_at` DATETIME,
  `updated_at` DATETIME,
  `deleted_at` DATETIME,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `password_reset_tokens`;
CREATE TABLE `password_reset_tokens` (
  `email` VARCHAR(255) NOT NULL,
  `token` VARCHAR(255) NOT NULL,
  `created_at` DATETIME
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `pricing_brand_prices`;
CREATE TABLE `pricing_brand_prices` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `brand_id` BIGINT UNSIGNED NOT NULL,
  `component_key` VARCHAR(255) NOT NULL,
  `price` BIGINT UNSIGNED,
  `created_at` DATETIME,
  `updated_at` DATETIME,
  UNIQUE KEY `pricing_brand_prices_brand_id_component_key_unique` (`brand_id`, `component_key`),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `pricing_brands`;
CREATE TABLE `pricing_brands` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `key` VARCHAR(255) NOT NULL,
  `name` VARCHAR(255) NOT NULL,
  `sort_order` BIGINT UNSIGNED NOT NULL DEFAULT 0,
  `is_active` TINYINT(1) NOT NULL DEFAULT 1,
  `created_at` DATETIME,
  `updated_at` DATETIME,
  `material` VARCHAR(255) NOT NULL DEFAULT 'upvc',
  UNIQUE KEY `pricing_brands_key_unique` (`key`),
  KEY `pricing_brands_material_index` (`material`),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `pricing_components`;
CREATE TABLE `pricing_components` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `key` VARCHAR(255) NOT NULL,
  `name` VARCHAR(255) NOT NULL,
  `unit` VARCHAR(255) NOT NULL DEFAULT 'meter',
  `sort_order` BIGINT UNSIGNED NOT NULL DEFAULT 0,
  `created_at` DATETIME,
  `updated_at` DATETIME,
  UNIQUE KEY `pricing_components_key_unique` (`key`),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `pricing_glasses`;
CREATE TABLE `pricing_glasses` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `key` VARCHAR(255) NOT NULL,
  `name` VARCHAR(255) NOT NULL,
  `price_per_sqm` BIGINT UNSIGNED NOT NULL DEFAULT 0,
  `sort_order` BIGINT UNSIGNED NOT NULL DEFAULT 0,
  `is_active` TINYINT(1) NOT NULL DEFAULT 1,
  `created_at` DATETIME,
  `updated_at` DATETIME,
  UNIQUE KEY `pricing_glasses_key_unique` (`key`),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `pricing_hardwares`;
CREATE TABLE `pricing_hardwares` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `key` VARCHAR(255) NOT NULL,
  `name` VARCHAR(255) NOT NULL,
  `price_turk` BIGINT UNSIGNED NOT NULL DEFAULT 0,
  `price_germany` BIGINT UNSIGNED NOT NULL DEFAULT 0,
  `sort_order` BIGINT UNSIGNED NOT NULL DEFAULT 0,
  `is_active` TINYINT(1) NOT NULL DEFAULT 1,
  `created_at` DATETIME,
  `updated_at` DATETIME,
  UNIQUE KEY `pricing_hardwares_key_unique` (`key`),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `pricing_leads`;
CREATE TABLE `pricing_leads` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `model_id` BIGINT UNSIGNED,
  `model_name` VARCHAR(255),
  `name` VARCHAR(255) NOT NULL,
  `phone` VARCHAR(255) NOT NULL,
  `width_cm` BIGINT UNSIGNED,
  `height_cm` BIGINT UNSIGNED,
  `quantity` BIGINT UNSIGNED NOT NULL DEFAULT 1,
  `profile_key` VARCHAR(255),
  `glass_key` VARCHAR(255),
  `hardware_origin` VARCHAR(255),
  `hardware_type_key` VARCHAR(255),
  `estimate` BIGINT UNSIGNED,
  `notes` TEXT,
  `status` VARCHAR(255) NOT NULL DEFAULT 'new',
  `created_at` DATETIME,
  `updated_at` DATETIME,
  KEY `pricing_leads_created_at_index` (`created_at`),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `pricing_models`;
CREATE TABLE `pricing_models` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `catalog_id` BIGINT UNSIGNED NOT NULL,
  `name` VARCHAR(255) NOT NULL,
  `tab` VARCHAR(255) NOT NULL DEFAULT 'windows',
  `category_key` VARCHAR(255) NOT NULL DEFAULT 'casement',
  `family` VARCHAR(255) NOT NULL DEFAULT 'casement',
  `glass_deduction` DOUBLE,
  `hardware_qty` BIGINT UNSIGNED NOT NULL DEFAULT 1,
  `hardware_mode` VARCHAR(255) NOT NULL DEFAULT 'fixed',
  `hardware_type_key` VARCHAR(255),
  `lites` BIGINT UNSIGNED NOT NULL DEFAULT 1,
  `sashes` BIGINT UNSIGNED NOT NULL DEFAULT 0,
  `transom_top` TINYINT(1) NOT NULL DEFAULT 0,
  `transom_bottom` TINYINT(1) NOT NULL DEFAULT 0,
  `panel_ratio` DOUBLE NOT NULL DEFAULT '0',
  `recipe` JSON,
  `recipe_locked` TINYINT(1) NOT NULL DEFAULT 0,
  `sort_order` BIGINT UNSIGNED NOT NULL DEFAULT 0,
  `is_active` TINYINT(1) NOT NULL DEFAULT 1,
  `created_at` DATETIME,
  `updated_at` DATETIME,
  `area_rate` BIGINT UNSIGNED,
  `image` VARCHAR(255),
  UNIQUE KEY `pricing_models_catalog_id_unique` (`catalog_id`),
  KEY `pricing_models_tab_category_key_index` (`tab`, `category_key`),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `pricing_settings`;
CREATE TABLE `pricing_settings` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `key` VARCHAR(255) NOT NULL,
  `label` VARCHAR(255),
  `value` LONGTEXT,
  `created_at` DATETIME,
  `updated_at` DATETIME,
  UNIQUE KEY `pricing_settings_key_unique` (`key`),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `product_categories`;
CREATE TABLE `product_categories` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `name` VARCHAR(255) NOT NULL,
  `slug` VARCHAR(255) NOT NULL,
  `sort_order` BIGINT UNSIGNED NOT NULL DEFAULT 0,
  `is_active` TINYINT(1) NOT NULL DEFAULT 1,
  `created_at` DATETIME,
  `updated_at` DATETIME,
  `deleted_at` DATETIME,
  PRIMARY KEY (`id`),
  UNIQUE KEY `product_categories_slug_unique` (`slug`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `products`;
CREATE TABLE `products` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `category_id` BIGINT UNSIGNED,
  `name` VARCHAR(255) NOT NULL,
  `slug` VARCHAR(255) NOT NULL,
  `product_type` VARCHAR(255),
  `short_description` TEXT,
  `description` LONGTEXT,
  `specifications` JSON,
  `image_close_id` BIGINT UNSIGNED,
  `image_open_id` BIGINT UNSIGNED,
  `alt_text` VARCHAR(255),
  `folder_number` BIGINT UNSIGNED,
  `sort_order` BIGINT UNSIGNED NOT NULL DEFAULT 0,
  `show_on_home` TINYINT(1) NOT NULL DEFAULT 0,
  `status` VARCHAR(255) NOT NULL DEFAULT 'published',
  `seo_title` VARCHAR(255),
  `seo_description` VARCHAR(255),
  `created_at` DATETIME,
  `updated_at` DATETIME,
  `deleted_at` DATETIME,
  `show_on_listing` TINYINT(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  UNIQUE KEY `products_slug_unique` (`slug`),
  KEY `products_status_sort_order_index` (`status`, `sort_order`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `projects`;
CREATE TABLE `projects` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `title` VARCHAR(255) NOT NULL,
  `slug` VARCHAR(255) NOT NULL,
  `type` VARCHAR(255) NOT NULL DEFAULT 'upvc',
  `type_label` VARCHAR(255),
  `summary` TEXT,
  `description` LONGTEXT,
  `image_id` BIGINT UNSIGNED,
  `alt_text` VARCHAR(255),
  `client_name` VARCHAR(255),
  `location` VARCHAR(255),
  `sort_order` BIGINT UNSIGNED NOT NULL DEFAULT 0,
  `show_on_home` TINYINT(1) NOT NULL DEFAULT 1,
  `status` VARCHAR(255) NOT NULL DEFAULT 'published',
  `seo_title` VARCHAR(255),
  `seo_description` VARCHAR(255),
  `created_at` DATETIME,
  `updated_at` DATETIME,
  `deleted_at` DATETIME,
  `show_on_listing` TINYINT(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  UNIQUE KEY `projects_slug_unique` (`slug`),
  KEY `projects_status_sort_order_index` (`status`, `sort_order`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `sessions`;
CREATE TABLE `sessions` (
  `id` VARCHAR(255) NOT NULL,
  `user_id` BIGINT UNSIGNED,
  `ip_address` VARCHAR(255),
  `user_agent` TEXT,
  `payload` LONGTEXT NOT NULL,
  `last_activity` BIGINT UNSIGNED NOT NULL,
  KEY `sessions_last_activity_index` (`last_activity`),
  KEY `sessions_user_id_index` (`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `settings`;
CREATE TABLE `settings` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `group` VARCHAR(255) NOT NULL DEFAULT 'general',
  `key` VARCHAR(255) NOT NULL,
  `label` VARCHAR(255),
  `type` VARCHAR(255) NOT NULL DEFAULT 'text',
  `value` LONGTEXT,
  `created_at` DATETIME,
  `updated_at` DATETIME,
  PRIMARY KEY (`id`),
  UNIQUE KEY `settings_key_unique` (`key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `users`;
CREATE TABLE `users` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `name` VARCHAR(255) NOT NULL,
  `email` VARCHAR(255) NOT NULL,
  `email_verified_at` DATETIME,
  `password` VARCHAR(255) NOT NULL,
  `role` VARCHAR(255) NOT NULL DEFAULT 'editor',
  `is_active` TINYINT(1) NOT NULL DEFAULT 1,
  `last_login_at` DATETIME,
  `remember_token` VARCHAR(255),
  `created_at` DATETIME,
  `updated_at` DATETIME,
  PRIMARY KEY (`id`),
  UNIQUE KEY `users_email_unique` (`email`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


SET FOREIGN_KEY_CHECKS=1;
