INSERT INTO `articles` (`id`, `title`, `slug`, `excerpt`, `body`, `cover_path`, `cover_alt`, `author`, `published_at`, `status`, `seo_title`, `seo_description`, `created_at`, `updated_at`, `deleted_at`, `show_on_listing`) VALUES
(1, 'استاندارد و کیفیت یک شیشه دوجداره مطلوب چیست؟', 'استاندارد-و-کیفیت-یک-شیشه-دوجداره-مطلو', 'استاندارد ساخت و مشخصات و ضخامت شیشه دوجداره و بهترین رنگ شیشه دوجداره چست؟ علت تزریق گاز آرگون و بخار گرفتگی وقیمت شیشه با گاز آرگون چقد', 'کلیه شیشه ها باید از جنس فلوت درجه یک و بدون خط و خش و اعوجاج بوده و حتی الامکان برای استفاده در اندازه های بزرگ و کاربرد در طبقات بالا و ارتفاع با فرآیند سکوریت یا لمینت تولید شود.\n\nقطر شیشه های دوجداره حتی الامکان بیش از 20 میلیمتر (ضخامت 24 میلیمتر ایده آل است) و حتما با ترکیب 4 و 6 میلیمتر لایه درونی و برونی تولید شود بین دو شیشه ها استفاده از اسپیسرهای آلومینیومی مرغوب و حتی الامکان با روش بندینگ ( عدم برش اسپیسرها در گوشه ها و به صورت خم ) فضای عایق ایجاد شود.\n\nشیشه های دوجداره با استفاده از ماشین آلات استاندارد و در فضای کارخانه ای ( نه به صورت دستی ) تولید و در فضای بین دو شیشه گاز آرگون به میزان 90 درصد حجم تزریق گردد.\n\nشیشه ها از نظر بخار گرفتگی و خروج گاز آرگون حداقل ضمانت 5 ساله داشته باشد. شستشوی شیشه ها نیز باید با استفاده از ماشین آلات و با کاربرد آب مقطر و درجه سختی مناسب انجام شود.\n\nچسب بوتیل اتصال شیشه به اسپیسر و چسب پلی سولفاید پر کننده پیرامون شیشه ها و نیز رطوبت گیرهای مصرفی باید از جنس مرغوب و از برندهای معتبر و به اندازه کافی استفاده شود. برای ارتفاع های زیاد از سطح دریا از سوپاپ تنظیم فشار هوا استفاده شود.<strong>از محصولات ما دیدن فرمایید</strong>\n    </div>', 'images/articles/استاندارد و کیفیت یک شیشه دوجداره مطلوب.webp', 'استاندارد و کیفیت یک شیشه دوجداره مطلوب چیست؟', 'admin', '2020-09-20 07:22:14', 'published', 'استاندارد و کیفیت یک شیشه دوجداره مطلوب چیست؟', 'استاندارد ساخت و مشخصات و ضخامت شیشه دوجداره و بهترین رنگ شیشه دوجداره چست؟ علت تزریق گاز آرگون و بخار گرفتگی وقیمت شیشه با گاز آرگون چقد', '2026-08-20 19:48:48', '2026-09-06 13:20:35', NULL, 1),
(2, 'انواع شیشه دوجداره', 'انواع-شیشه-دوجداره', 'شیشه دوجداره چیست؟ مبنای ساخت شیشه های دوجداره، تعبیه فضای خالی بین چند لایه شیشه است. شیشه دوجداره از دو یا چند لایه شیشه تشکیل شده که توسط میله یا…', '<h2>شیشه دوجداره چیست؟</h2>مبنای ساخت شیشه های دوجداره، تعبیه فضای خالی بین چند لایه شیشه است. شیشه دوجداره از دو یا چند لایه شیشه تشکیل شده که توسط میله یا اسپیسر جداکننده (spacer) از یکدیگر فاصله می گیرند. در این فضای خالی هوا یا گازی مخصوص بدون رطوبت ( آرگون یا کریپتون ) با فشاری تقریباً مساوی با هوای بیرون قرار می گیرد. این لایه های شیشه در شرایط کنترل شده کارخانه ای به اسپیسر جداکننده با استفاده از درزگیر غیرقابل نفوذی می چسبند. درون اسپیسر جداکننده، با ماده رطوبت گیر پر شده که این ماده سبب جذب بخار و رطوبت هوای فضای بین دو شیشه می گردد.<h2>انواع شیشه دوجداره</h2><ul><li>شیشه فلوت یا ساده</li><li>شیشه سکوریت</li><li>شیشه لمینت</li><li>شیشه سند بلاست</li><li>شیشه رفلکس</li><li>شیشه رنگی</li><li>شیشه مشجر ، مات</li><li>شیشه شناور</li><li>شیشه تابکاری شده</li><li>شیشه عایق</li><li>شیشه کنترل کننده انرژی</li><li>شیشه سیمی</li></ul><h3>شیشه فلوت یا ساده</h3>شیشه ساده شیشه ای است ه هیچ نوع فرآیندی برای بهبود شیشه روی آن صورت نگرفته است در واقع شیشه ساده به همان طورت که از کوره بیرون می آید مورد استفاده قرار میگیرد و دارای ویژگی های خاصی نمی باشد و ضعیفتر از سایر شیشه ها نیز می باشد<h3>شیشه سکوریت</h3>شیشه سکوریت شیشه ای است که طی یک فرآیند گرم شدن با دمای بالا و سرد شدن به صورت سریع می باشد در این فرآیند شیشه می تواند یکسری از ویژگی ها را در خود از جمله مقاومت بالا در برابر فشار و ضربه بگنجاند. در این نوع از شیشه دوجداره ، شیشه برای موارد ایمنی بالا چه از لحاظ گرما ، ضربه ، فشار مورد استفاده قرار میگیرد<h3>شیشه لمینت</h3>شیشه لمینت نیز یکی دیگر از شیشه های با مقاومت بالا می باشد که از دو شیشه در کنار هم که در وسط آنها از یک لایه ژله ای پر شده است ساخته می شود . شیشه در هنگام خورد شدن در داخل این ماده ژله ای فرو می رود و مانع پخش شیشه می شود<h3>شیشه سند بلاست</h3>یکی دیگر از انواع شیشه دوجداره شیشه سند بلاست می باشد در واقع فرآیند سندبلاست فرآیندی می باشد که طی آن با استفاده از ماسه و آب روی شیشه طرح هایی قرار داده می شود که باعث مات شدن و زیبا شدن شیشه می شود<h3>شیشه مشجر یا مات</h3>شیشه هایی هستند که دارای طرح های خاصی روی شیشه می باشند شیشه مات هر نوع شیشه‌ای است که اجازه ورود نور را می‌دهد، اما به راحتی نمی‌توان سمت دیگر شیشه را مشاهده کرد. شیشه پنجره مات ممکن است خود به تنهایی دارای انواع الگوی طرح‌دار باشد که می‌توان برحسب علاقه و موقعیت استفاده هر کدام را انتخاب کرد. در بین انواع شیشه پنجره، این نوع محبوب‌ترین مدل برای شیشه حمام، اتاق‌های دوش و درب ورودی مراکز تجاری و شرکت‌های بزرگ است. به طور کلی، شیشه مات معمولاً برای هر فضایی که نیاز به کاهش دید از بیرون دارد مورد استفاده قرار می‌گیرد.<h3><strong>شیشه</strong>پنجره دوجداره<strong>رنگی</strong></h3>پنجره دوجداره آوان: این نوع شیشه از یک جداره رنگی و یک جداره ساده تشکیل شده است . شیشه رنگی هر نوع شیشه‌ای است که رنگ آمیزی به آن اضافه شده است. این امر به دلایل مختلفی از جمله طراحی، زیبایی شناختی، حفظ حریم خصوصی و کاهش گرمای ناشی از نور خورشید قابل انجام است. شیشه رنگ شده همچنین می‌تواند نوعی محافظت در برابر اشعه ماوراء بنفش که برای پوست مضر است باشد. شما معمولاً شیشه‌های رنگ شده را روی خودروها، پنجره‌های شیروانی و پنل‌های تزئینی مشاهده کنید، اما می‌توانید برای حریم خصوصی بیشتر آنها را برای پنجره‌های خارجی خانه یا محل کار خود نیز استفاده کنید.<h3><strong>شیشه</strong>پنجره دوجداره<strong>رفلکس</strong></h3>پنجره دوجداره آوان: این نوع<strong>شیشه دو جداره</strong>از یک جداره ساده و یک جداره<strong>شیشه رفلکس</strong>ساخته می شود که جداره شیشه رفلکس باید به طرف بیرون قرار گیرد .<strong>شیشه های رفلکس</strong>از عبور نور شدید خورشید به شدت جلوگیری می کنند ولی ایراد آنها این است که داخل ساختمان را تاریک کرده و در شب داخل ساختمان نمایان است .<h3><strong>شیشه تابکاری شده</strong></h3>یکی دیگر از انواع شیشه پنجره، شیشه تابکاری شده یا آنیل شده است. آنیلینگ فرآیند آهسته، دقیق و کنترل شده برای خنک کردن پنل‌های شیشه شناور است. هدف از این فرآیند تقویت شیشه با کاهش استرس ناشی از خنک کنندهِ سریع است. این معمولاً قدم بعدی برای شیشه شناور است و اکنون می‌توان برای آن به روزرسانی‌های بیشتری انجام داد. شیشه‌های تبکاری شده یا آنیل شده گزینه‌ای مناسب برای پنجره نیست، زیرا اگر شکسته شوند، قطعات بزرگ و تیزی از خود باقی می‌گذارند.<h3><strong>شیشه عایق</strong></h3>یکی دیگر از انواع شیشه پنجره، شیشه عایق است که برای بهره وری انرژی در فضاهای مختلف مورد استفاده قرار می‌گیرد. این شیشه ممکن است دو یا سه جداره داشته باشد که آرگون در فضای بین صفحات قرار می‌گیرد. جام‌های شیشه در یک واحد عایق که معمولاً شیشه لمینیت یا شیشه تابکاری شده است حرارت داده می‌شوند. شیشه عایق گزینه مناسبی برای شیشه‌های بیرونی خانه، محل کار و محیط‌های داخلی دیگر است که به شما کمک می‌کند تا هزینه‌های گرمایش و سرمایش کاهش یابد. همه واحدهای شیشه عایق به طور مساوی ایجاد نمی‌شوند، بنابراین حتماً انتخاب خود را برای بهترین درجه بهره وری انرژی مقایسه کنید تا شیشه مناسب را خریداری کنید.<h3><strong>شیشه کنترل کننده انرژی (</strong><strong>Low-E Glass</strong><strong>)</strong></h3>این شیشه به‌طور خاص تولید می‌شود تا تابش حرارت را منعکس کند. پوشش کمی از الکترونیکی اشعه مادون قرمز را حفظ می‌کند، در حالی که هنوز هم نور از آن عبور می‌کند. چرا این موضوع برای خانه‌ها بسیار مفید است؟ در طول تابستان، گرما از طریق پنجره به داخل محیط وارد و فضا را گرم می‌کند و در زمستان این اتفاق به‌شکلی برعکس رخ می‌دهد. این به معنی کاهش هزینه‌های گرمایشی و سرمایشی است. شیشه کنترل کننده انرژی می‌تواند یک سرمایه گذاری بلند مدت باشد که به پس انداز بیشتر هزینه‌ها کمک می‌کند.<h3><strong>شیشه سیمی (</strong><strong>Wired Glass</strong><strong>)</strong></h3>شیشه سیمی لزوماً یک شیشه امنیتی محسوب نمی‌شود، اما مقاوم در برابر حرارت است. به‌همین دلیل بیشتر در مدارس، بیمارستان‌ها و سایر ساختمان‌های تجاری مورد استفاده قرار می‌گیرد. شبکه سیم‌های ساخته شده در این شیشه پنجره اگر در زیر گرمای زیاد مانند آتش سوزی ساختمان قرار گیرد، فرم شیشه را نگه می‌دارد و از ریزش آن جلوگیری می‌کند. در حالی که شیشه سیمی برای بسیاری از ساختمان‌های تجاری و آسمان خراش‌ها کاربرد دارد، به‌ندرت آن را می‌توان در ساختمان‌های مسکونی چند طبقه مشاهده کرد.<h3>شیشه شناور</h3><div><div><a href="https://fa.wikipedia.org/wiki/%D8%B4%DB%8C%D8%B4%D9%87_%D8%B4%D9%86%D8%A7%D9%88%D8%B1"><b>شیشه شناور</b></a>یک ورق شیشه ایی است که توسط شیشه مذاب شناور بر روی بستری از فلز مذاب (معمولاً قلع) ساخته می‌شود البته در گذشته از فلزاتی چون سرب و آلیاژهایی با نقطه ذوب پایین استفاده می‌شد. با این روش ورق تولید شده دارای سطح بسیار صاف و ضخامت یکنواخت در طول خود می‌باشد. امروزه پنجرهای جدید از شیشه‌های شناور ساخته می‌شوند، ماده اولیه اکثریت شیشه‌های شناور از جنس شیشه‌های آهک سوددار می‌باشند اما مقادیر نسبتاً اندکی نیز به بوروسیلیکات اختصاص می‌یابد، از این شیشه‌ها بیشتر در فرایند ذوب شیشه استفاده می‌کنند نام دیگر فرایند تولید شیشه شناور پیلکینگتون(Pilkington) می‌باشد چراکه تکنیک ساخت این نوع شیشه توسط آقای الستر پیلکینگتون(Alastair pilkington) در سال ۱۹۵۰ اختراع شده‌است.</div></div>\n    </div>', 'images/articles/انواع شیشه دوجداره.webp', 'انواع شیشه دوجداره', 'admin', '2021-05-25 11:41:21', 'published', 'انواع شیشه دوجداره', 'شیشه دوجداره چیست؟ مبنای ساخت شیشه های دوجداره، تعبیه فضای خالی بین چند لایه شیشه است. شیشه دوجداره از دو یا چند لایه شیشه تشکیل شده که توسط میله یا…', '2026-08-20 19:48:48', '2026-09-06 13:20:35', NULL, 1),
(3, 'انواع شیشه دکوراتیو', 'انواع-شیشه-دکوراتیو', 'شیشه‌های دکوراتیو در طرح‌ها و انواع متفاوت تولید می‌شوند. همین موضوع باعث شده است تا استفاده از شیشه‌های دکوراتیو در دکوراسیون داخلی و خارجی ساختمان‌ها…', 'شیشه‌های دکوراتیو در طرح‌ها و انواع متفاوت تولید می‌شوند. همین موضوع باعث شده است تا استفاده از شیشه‌های دکوراتیو در دکوراسیون داخلی و خارجی ساختمان‌ها رواج پیدا کند. اگر دوست دارید از یک دکوراسیون شیک و خاص برای منزل یا محل کارتان بهره ببرید، در ادامه با ما همراه باشید تا با انواع شیشه‌های دکوراتیو آشنا شوید.<h3><strong>شیشه دکوراتیو سند بلاست (</strong><strong>Sandblast)</strong></h3>سند بلاست (sandblast) به معنای پاشش ماسه مخصوص بر روی شیشه است. شیشه‌هایی که با روش پاشش ماسه دکوراتیو می‌شوند مات هستند و برای مکان‌هایی مانند دیوار اتاق و حمام مناسب هستند. شیشه‌های دکوراتیو سند بلاست قابلیت طرح پذیری خوبی دارند و به راحتی می‌توانید طرح دلخواه‌تان از جمله لوگوی شرکت‌تان را روی آن ایجاد کنید. در واقع شیشه‌های سند بلاست را می‌توانید برای تمام مکان‌ها و با کاربردهای متفاوت استفاده کنید تا محیط از سادگی و یکنواختی خارج شود.<h3><strong>شیشه دکوراتیو سند بلاست رنگی</strong></h3>شیشه دکوراتیو سند بلاست رنگی در واقع همان شیشه شفاف است که بعد از فرآیند سند بلاست، به روش‌ها مختلف رنگی می‌شود. این شیشه‌ها توسط قلم‌مو و چاپ رنگی می‌شوند. در یک تعریف ساده، شیشه سند بلاست رنگی ترکیبی از سند بلاست و رنگ است.<h3><strong>شیشه دکوراتیو لمینت و سکوریت رنگی</strong></h3>شیشه‌های لمینت دکوراتیو شده برای دکوراسیون تمام قسمت‌های ساختمان قابل استفاده است و کاربرد دارد. شیشه‌های دکوراتیو لمینت رنگی شده، معمولا توسط شرکت‌های اروپایی معتبر و در طیف رنگی گسترده، به صورت مات و شفاف تولید و توزیع می‌شود. شیشه‌های دکوراتیو لمینت رنگی، از چندین لایه شیشه تخت تهیه می‌شود که توسط لایه PVB به همدیگر متصل می‌شوند. شیشه لمینت رنگی، علاوه بر ظاهر زیبا، عایق صوت و حرارت نیز هست و در برابر اشعهUV و ضربه هم مقاومت دارد. شیشه سکوریت قابلیت تولید در رنگ‌ها متنوع از جمله سبز، سفید، دودی، برفی و آبی را دارد.<h3><strong>شیشه دکوراتیو لاکوبل (</strong><strong>Lacobel)</strong></h3>شیشه دکوراتیو لاکوبل، به نوعی از شیشه گفته می‎‌شود، که بعد از عملیات رنگ شدن به وسیله یک لایه از PVC پوشانده می‌شود. با این کار هم شیشه ایمنی بیشتری پیدا کند و مقاوم‌تر می‌شود و هم از رنگ زده شده روی شیشه محافظت می‌شود. این شیشه‌ها در رنگ بندی متنوع و ضخامت‌ها متفاوت تولید می‌شود و همین امر سبب شده است تا این نوع شیشه کاربرد بسیاری در طراحی دکوراسیون داخلی و خارجی داشته باشد.\n\nشیشه لاکوبل معمولا معمولا به صورت خام تهیه می‌شود و به صورت مات و شفاف در بازار وجود دارد. برخی از کارخانه‌ها قادر اند فرآیند سکوریت کردن را روی شیشه‌های لاکوبل رنگی اجام دهند. شیشه‌های لاکوبل به دلیل عملیات حرارتی معمولا مات هستند. تولید این نوع از شیشه‌ها به صنعت سبز مشهور است، زیرا برای تولید آن‌ها هیچ گونه آلودگی به محیط وارد نمی‌شود و در تولیدشان هیچ ماده شیمیایی مضری برای محیط زیست استفاده نمی‌شود.<h3><strong>شیشه دکوراتیو طرح مات (</strong><strong>Matelux)</strong></h3>مات کردن شیشه یا به عبارت دیگر دکوراتیو شیشه به صورت مات، با کمک نوعی اسید انجام می‌شود. این نوع از شیشه در برابر لک و کثیف شدن عملکرد خوبی از خودشان نشان می‌دهند و نور را نیز از خود عبور نمی‌دهند. شیشه‌های دکوراتیو مات را می‌توانید با خیال راحت به شیشه بری ببرید تا طرح دلخواه‌تان را روی آن برش بزنند. شیشه دکوراتیو مات در رنگ‌بندی متنوع تولید می‌شود و برای افزایش امنیت آن از یک لایه لمینت و چسب پلی سولفاید روی شیشه استفاده می‌شود.<h3><strong>شیشه دکوراتیو چاپ‌دار (</strong><strong>Spandrel)</strong></h3>شیشه دکوراتیو چاپ‌دار نوع دیگری از شیشه‌های مات است که در رنگ‌های متنوع در بازار موجود است. چاپ روی شیشه دکوراتیو توسط چاپ UV صورت می‌گیرد و هر عکسی را که دوست داشته باشید به دلخواه خودتان می‌توانید روی آن چاپ کنید. این شیشه‌ها به کمک یراق آلات مخصوص در هر جایی از ساختمان، از جمله ویترین، کابینت و فضای باز بین اتاق‌ها قابل نصب است.\n\nدر رابطه با این شیشه‌ها، برای افزایش استحکام و مقاومت در برابر حرارت و ضربه، پیشنهاد می‌شود، چاپ روی شیشه‌هایی همچون میرال یا سکوریت انجام شود. به عبارت دیگر، شیشه بعد از تولید، داخل دستگاه مخصوص چاپ قرار می‌گیرد و طرح مد نظر با کیفیت بالا روی آن چاپ می‌شود.<h3><strong>شیشه دکوراتیو طرح شیشه شکسته</strong></h3>این نوع از شیشه‌ها به گونه‌ای طراحی می‌شوند که گویی شیشه شکسته است، ولی در اصل این ظاهر فقط برای زیبایی به کار می‌رود. شیشه دکوراتیو طرح شیشه شکسته بر خلاف نامی که دارد و بر خلاف تصور عموم مقاومت بالایی دارد و در برابر ضربه کاملا مقاوم است. این نوع از شیشه‌ها معمولا در ساخت کف‌های شیشه‌ای و راه پله‌ها استفاده می‌شوند.<h3><strong>شیشه دکوراتیو طرح سنگ</strong></h3>اگر عاشق طبیعت هستید و دوست دارید در دکوراسیون منزل‌تان از المان‌های طبیعی استفاده کنید، احتمالا شیشه دکوراتیو طرح سنگ ایده آل شماست و با سلیقه‌تان سازگار است. در اینجا منظور استفاده از خود سنگ نیست، بلکه منظور شیشه‌های دکوراتیو شده طرح سنگ است که با کمک الگو برداری از طرح و بافت سنگ‌های طبیعی و با بهره گیری از پیشرفته‌ترین فناوری‌های روز دنیا به وجود آمده است. این نوع شیشه‌ها، الگوی بعضی از سنگ‌ها از جمله سنگ مرمر را دارند. انسان با کمک فناوری‌های جدید و پیشرفته توانسته است این نوع شیشه‌ها را در رنگ‌ها و طرح‌های متنوع تولید کند.شیشه‌های دکوراتیو، بازتاب نور و شفافیت فوق‌العاده‌ای دارند و همانند دیگر شیشه‌ها در برابر آب، گرما، سرما و رطوبت کاملا مقاوم هستند. این شیشه‌ها رنگ‌شان ثابت است و قابلیت برش در انواع ضخامت و ابعاد، حتی کوچک‌ترین سایزها را نیز دارند. شیشه‌های دکوراتیو طرح سنگ برای تمام قسمت‌های ساختمان قابل استفاده هستند. به عنوان مثال می‌توان برای حمام، آشپزخانه، پله‌ها، کف، دیوارها و دیگر بخش‌ها از شیشه دکوراتیو طرح سنگ استفاده کرد.\n    </div>', 'images/articles/انواع شیشه دکوراتیو.webp', 'انواع شیشه دکوراتیو', 'admin', '2020-11-01 12:13:17', 'published', 'انواع شیشه دکوراتیو', 'شیشه‌های دکوراتیو در طرح‌ها و انواع متفاوت تولید می‌شوند. همین موضوع باعث شده است تا استفاده از شیشه‌های دکوراتیو در دکوراسیون داخلی و خارجی ساختمان‌ها…', '2026-08-20 19:48:48', '2026-09-06 13:20:35', NULL, 1),
(4, 'بررسی انواع پنجره دوجداره از لحاظ قیمت، کیفیت و ساخت', 'بررسی-انواع-پنجره-دوجداره-از-لحاظ-قیمت', 'اینجا عوامل مربوط به تولید یک پنجره دوجداره upvc با کیفیت و انواع پنجره های دوجداره upvc عوامل تاثیر گذار در قیمت پنجره ها دوجداره بررسی', '<h2>آلوین پنجره، تولید کننده انواع پنجره دوجداره در ایران</h2>این روزها استفاده از درب و پنجره های دوجداره یا همان upvc در ساختمان سازی بسیار رایج شده است. ماده upvc از مشتقات نفت خام تهیه می شود و به گونه ای خاص ساخته شده است تا در برابر گرما، سرما و سایر شرایط آب و هوایی و تغییرات محیطی مقاوم باشد و تغییر شکل ندهد. بر اساس نیاز هر سازه،<strong>انواع پنجره دوجداره</strong>در بازار به فروش می رسند. هر کدام از این نمونه ها ویژگی های منحصر به فرد خود را دارد. بر خلاف ظاهر ظریف این نوع پنجره ها، امنیت پنجره های دوجداره بسیار بالا می باشد و استحکام بیشتری نسبت نمونه های قدیمی ( آهنی، آلومینیومی ) دارند. ساختار شبکه ای upvc باعث شده است که درب و پنجره دوجداره ساخته شده، در برابر فشار و ضربه بسیار مقاوم باشند.\n\nنمونه پنجره دوجداره آکاردئونی\n\nدر صنعت ساختمان سازی نوین، دیگر نمی توان سازه ای را بدون چنین درب و پنجره هایی تصور کرد. پنجره های دوجداره در سایز ها متنوع و در محل های گوناگون قابل نصب هستند. به طوری که امروزه در ساختمان های مسکونی، مراکز تجاری، دفاتر و... از این نوع استفاده می شود.\n\nطرح اولیه پنجره دوجداره آکاردئونی\n\nتوجه به بهینه سازی مصرف سوخت، اهمیت استفاده از پنجره دوجداره را بسیار افزایش داده است. فضای میان دو لایه شیشه استفاده شده در ساخت این نوع پنجره ها، با نوعی گاز پر شده است و این گاز به عنوان عایق حرارتی از اتلاف گرما در فصول سرد سال و ورود حرارت در فصول گرما سال جلوگیری می کند. به این ترتیب در هر فصل به نوعی از اتلاف انرژی جلوگیری می کند.<h2>بهترین پنجره دوجداره ویژگی هایی دارد که در ادامه به تعدادی از آن ها اشاره شده است :</h2><ul><li>موثر در کاهش ورود آلودگی هوا ( به علت انجام فرآیند آب بندی به صورت کامل )</li><li>نصب سریع و بسیار آسان</li><li>مقاومت مطلوب در برابر اشعه بنفش خورشید و جلوگیری از اثرات مخرب آن</li><li>صرفه جویی در مصرف انرژی در تمام طول سال ( در حدود 47 درصد که این رقم در هزینه ها بسیار تاثیر گذار است )</li><li>مقاومت در برابر تغییرات آب و هوایی مانند طوفان و بارندگی های شدید</li><li>در زمان افزایش اختلاف دما در داخل و خارج ساختمان ها از ایجاد میعان و عرق کردن شیشه ها جلوگیری می کند</li><li>عدم نیاز به تعویض، رنگ آمیزی و سرویس کردن پنجره ها</li><li>ثبات و ماندگاری رنگ در گذر زمان</li><li>امکان طراحی در ابعاد و اشکال هندسی مختلف بر مبنای شیوه معماری ساختمان</li><li>موثر در اصل سبک سازی ساختمان ها و افزایش ایمنی در هنگام وقوع زمین لرزه</li><li>غیر قابل اشتغال</li><li>امکان نصب حفاظ، توری، انواع کرکره ها و...</li><li>امکان نظافت راحت و آسان پنجره ها</li><li>وجود تنوع در طرح و شیوه باز شدن پنجره ها</li><li>افزایش ارزش ملک و ساختمان ها</li></ul>این ها تنها بخشی از مزیت های استفاده از پنجره های دوجداره می باشد. مجموعه آلوین پنجره از معدود ترین تولید کننده های<strong><a href="https://alwinco.ir/product/%D9%BE%D9%86%D8%AC%D8%B1%D9%87-%D8%AF%D9%88%D8%AC%D8%AF%D8%A7%D8%B1%D9%87-upvc-%D8%A2%DA%A9%D8%A7%D8%B1%D8%AF%D8%A6%D9%88%D9%86%DB%8C-%D8%B3%D9%87-%D9%84%D9%86%DA%AF%D9%87/"> پنجره دوجداره آکاردئونی </a></strong>در کشور می باشد. کیفیت بالا و قیمت مناسب محصولات این دلیل اصلی موفقیت آن در میان دیگر رقبای خود در این صنعت بوده است. از طریق وب سایت آلوین پنجره شما می توانید پنجره دوجداره با کیفیت و مرغوب را به صورت مستقیم و بدون واسطه به قیمت کارخانه خریداری کنید. تیم پشتیبانی مجموعه آماده کمک و خدمات رسانی به مشتریان در زمینه انتخاب<strong> انواع پنجره دوجداره </strong>هستند و به این ترتیب شما می توانید تشخیص دهید که<strong>کدام مدل پنجره دوجداره مناسب منزل شماست؟</strong>انواع پنجره دوجداره در ابعاد و طرح های متنوع<h2>بررسی قیمت درب و پنجره دوجداره</h2>همانند دیگر محصولات موجود در بازار اولین عامل تاثیر گذار در قیمت<strong>انواع درب و پنجره دوجداره</strong>، برند و کیفیت ساخت محصول می باشد. طبیعی است که در ساخت انواع پنجره دوجداره مرغوب و با کیفیت، از مواد بهتری استفاده می شود و فرآیند ساخت نیز پیچیده تر می باشد. تمامی این موارد نیازمند صرف هزینه و به کارگیری نیروی انسانی بیشتر برای تولید کننده می باشد. بنابراین این مسئله در قیمت گذاری نهایی درب و پنجره بسیار موثر است.\n\nاز دیگر موارد مرتبط با قیمت درب و پنجره دوجداره می توان به موارد زیر اشاره کرد :<ol><li>مدل پنجره</li></ol>همانطور که پیش تر به آن اشاره کردیم، پنجره ها دوجداره در طرح های گوناگون، قابل تولید هستند. بدیهی است که نمونه های ساده تر قیمت پایین تری نسبت به<strong> انواع پنجره دوجداره </strong>با طرح های پیچیده دارند.<ol><li>جنس پروفیل استفاده شده در ساخت فریم پنجره دوجداره</li></ol>پروفیل از اصلی ترین اجزا پنجره های دوجداره به حساب می آید. جنس پروفیل و میزان استفاده از آن در ساخت پنجره ها، بیشترین تاثیر را در کیفیت محصول حاصل و قیمت آن دارد. پروفیل های باکیفیت در برابر آلودگی هوا، گرما و تغییرات جوی بسیار مقاوم هستند. معمولا عمر مفید نمونه های باکیفیت بالاتر از سایر محصولات می باشد و انتخاب چنین پنجره هایی از نظر اقتصادی به صرفه تر است. بنابراین بهتر است که پیش از خرید به ویژگی های نمونه های مرغوب آشنا باشید. پروفیل های UPVC بسیار مقاوم هستند و تا سالیان زیادی بدون هیچ گونه تغییر و آسیبی، قابل استفاده هستند. چنین پروفیل هایی در برابر شعله های آتش نیز بسیار مقاوم هستند و از این نظر ایمنی بالایی دارند.\n\n3. رنگ پروفیل پنجره ها\n\nرنگ پروفیل یکی از موارد جذابی است که اغلب مشتریان به آن بسیار اهمیت می دهند. بسته به رنگ نما ساختمان و شیوه معماری آن می توان پروفیل ها را در رنگ های متنوعی سفارش داد. در برخی موارد ممکن است رنگ دلخواه مشتری، در افزایش قیمت نهایی<strong> انواع پنجره دوجداره </strong>تاثیر گذار باشد.\n\nپروفیل پنجره های دوجداره در رنگ های متنوع قابل تهیه هستند\n\nآلوین پنجره تولید کننده<strong> بهترین پنجره دوجداره </a></strong>آکاردئونی با قیمت مناسب و بسیار به صرفه در ایران می باشد. مشتریان عزیز می توانند در وب سایت این شرکت از خدمات استعلام<strong>قیمت آنلاین انواع پنجره دوجداره</strong>بهره مند شوند. برای محاسبه آنلاین قیمت محصول می توانید به قسمت<strong><a href="http://alwinco.ir/pricing"> محاسبه آنلاین قیمت پنجره دوجداره </a></strong>مراجعه کنید و در آنجا پس از تعیین مدل پنجره، مواد اولیه مورد استفاده در ساخت آن و ابعاد و اندازه، می توانید هزینه نهایی ساخت پنجره دوجداره مد نظرتان را به صورت آنلاین و کاملا رایگان مشاهده کنید.\n    </div>', 'images/articles/بررسی انواع پنجره دوجداره از لحاظ قیمت، کیفیت و ساخت آلوین پنجره، تولید کننده انواع پنجره دوجداره در ایران.webp', 'بررسی انواع پنجره دوجداره از لحاظ قیمت، کیفیت و ساخت', 'admin', '2022-01-17 12:30:48', 'published', 'بررسی انواع پنجره دوجداره از لحاظ قیمت، کیفیت و ساخت', 'اینجا عوامل مربوط به تولید یک پنجره دوجداره upvc با کیفیت و انواع پنجره های دوجداره upvc عوامل تاثیر گذار در قیمت پنجره ها دوجداره بررسی', '2026-08-20 19:48:48', '2026-09-06 13:20:35', NULL, 1),
(5, 'بهترین برند یا مارک پنجره دوجداره چیست؟', 'بهترین-برند-یا-مارک-پنجره-دوجداره-چیست', 'بهترین مارک پنجره دوجداره upvc یا بهترین برند پروفیل پنجره دوجداره چیست؟ بین پروفیل وین تک و ویستابست کدام بهتر و ارزانتر هست. قیمت یراق آلات ترکی یا آلمانی', '<h2>کدام پنجره دوجداره بهتر است ؟ یا بهترین مارک پنجره دوجداره upvc ؟</h2>این دو سوال به عنوان دو سوال بسیار مهمی می باشند که توسط بیشتر افراد خریداری پنجره دو جداره از ما پرسیده می شود در این پست آموزشی قصد داریم شما را به گونه ای راهنمایی کنیم تا با بهترین پنجره دوجداره مناسب خود آشنا شوید.\n\nبرای شناخت<strong> بهترین پنجره دوجداره </strong>لازم است که پنجره را در موارد مختلفی دسته بندی کنیم چرا که هر دسته می تواند یک معیار برای معرفی<strong> بهترین پنجره دو جداره یو پی وی سی <strong>از دید شما باشد چرا که هر محل نصب قطعا دارای ویزگی های خاص خود می باشد و می تواند معیار های خاص خود را داشته باشد.<h2>به طور کلی می توان فاکتورهای کلی را برای معرفی بهترین پنجره دوجداره upvc در نظر گرفت که در اینجا به ذکر آن نیز می پردازیم:</h2>مهم ترین فاکتورهایی که برای پنجره ی یو پی وی سی وجود دارد:\n\n۱- نوع پروفیل UPVC یا آلومینیویم\n\n۲- نوع یراق آلات ، ترک یا آلمانی بودن\n\n۳- تولید استاندارد و مطابق با دفترچه الزامات فنی شرکت ویستابست\n\n۴- نوع شیشه دوجداره بکار رفته. شیشه دوجداره باید تمام بصورت صنعتی تولید شده باشد تا گاز آرگون تزریق شده به راحتی خارج نگردد.\n\n۵- نصب استاندارد توسط پیچ های ۱۰ سانتی متری بولدکس و آب بندی و هوابندی با چسب سیلیکن و فوم پلی ارتان<h2>بهترین مارک پنجره دوجداره</h2>مارک های مختلفی از پنجره دوجداره در بازار موجود می باشد که هر کدام از آنها دارای ویزگی های خاص خود می باشند و دارای قیمت های مختلفی می باشند یکی از فاکتورهای موثر در قیمت پنجره دوجداره upvc همین مارک یو پی وی سی می باشد به طور کلی سه مدل پروفیل در بازار بیشترین استفاده را دارد<ol><li><strong>وین تک</strong></li><li>ویستا بست</li><li>هافمن</li></ol>برند های دیگری نیز برای پروفیل پنجره دو جداره موجود می باشد اما این سه برند بیشترین تقاضا را دارند در ادامه به بررسی این سه پروفیل می پردازیم\n\nهر دو<strong> پروفیل وین تک </strong>و ویستا بست در رده های مختلفی از کیفیت موجود می باشد لازم است بدانید اگر به دنبال بهترین برند پنجره یو پی وی سی می باشید و یکی از انواع پروفیل ها را انتخاب کرده اید باید به این نکته نیز توجه کنید که در برخی از موارد دیده شده است از پروفیل های تقلبی نیز به عنوان پروفیل های معتبر استفاده می کنند پس حتما در هنگام خرید و نصب پنجره دوجداره این نکته را نیز به خاطر داشته باشید که احتمال اینکه پروفیل تقلبی باشد نیز وجود دارد پس سعی کنید برای نصب پنجره upvc از دفاتر نصب معتبر کمک بگیرد\n\nمارک های گوناگونی از پنجره دوجداره در بازار وجود دارد که هرکدام از این برندها می تواند ویژگی های مخصوص به خود را داشته باشند و همین ویژگی ها می تواند تعیین کننده ی قیمت آن ها باشد. یکی از فاکتورهای بسیار اساسی و تاثیرگذار در<strong>قیمت پنجره دوجداره upvc</strong>همین مارک upvc می باشد.\n\nیکی از برندهای معتبر که از کیفیت خوبی نیز برخوردار است پروفیل upvc ویستابست می باشد. ویستابست در<strong> دو نوع سری ۶۰ </strong>و<strong> سری ۷۰ </strong>قابلیت تولید دارد.<h2>مقایسه پروفیل وین تک و ویستابست</h2>پروفیل ویستابست از پروفیل وین تک گرانتر می باشد پروفیل ویستابست از وین تک سنگین تر می باشد در عوض پروفیل وین تک دارای حرفه های بیشتری می باشد ضخامت در دیواره های خارجی در پروفیل خانواده ویستابست بیشتر می باشد و پروفیل وین تک سطح مقاومت بیشتری نسبت به پروفیل ویستا بست دارد\n\nهر دو پروفیل یعنی وین تک و ویستا بست همانگونه که اشاره شد دارای رنج های مختلفی می باشند که هر کدام دارای ویزگی های خاص خود می باشد لازم است بدانید این دو پروفیل سالیان طولانی است که به عنوان پروفیل های درب و پنجره دوجداره مورد استفاده قرار میگیرند.<h2>نتیجه گیری بهترین مارک پروفیل پنجره دو جداره</h2>جهت مصارف تعویض پنجره بهترین پیشنهاد پنجره UPVC ویستابست با یراق آلمانی ROTO پیشنهاد می گردد. در مصارف نوسازی اگر ابعاد پنجره هایتان استاندارد است و بدنبال یک پنجره خوب و با قیمت خوب هستید باز هم ویستابست پیشنهاد می گردد. اگر در پروژه های نوسازی تنوع رنگ براینان مهم است بهتر است از پنجره ترمال بریک با انواع رنگ های پودری و آنادایز استفاده نمایید. اگر سایز پنجره های شما بزرگ است بهترین پیشنهاد استفاده از پنجره آلومینیویم ترمال بریک است. اگر به دنبال<strong>پنجره های کشویی</strong>سایز بزرگ و با ارتفاع زیاد هستید و بدون کتیبه حتما از پنجره دوجداره آلومینیومی لیفت اند اسلاید و یا انواع کشویی استفاده نمایید.\n    </div>', 'images/articles/بهترین برند یا مارک پنجره دوجداره جنریت .webp', 'بهترین برند یا مارک پنجره دوجداره چیست؟', 'admin', '2020-06-16 15:40:37', 'published', 'بهترین برند یا مارک پنجره دوجداره چیست؟', 'بهترین مارک پنجره دوجداره upvc یا بهترین برند پروفیل پنجره دوجداره چیست؟ بین پروفیل وین تک و ویستابست کدام بهتر و ارزانتر هست. قیمت یراق آلات ترکی یا آلمانی', '2026-08-20 19:48:48', '2026-09-06 13:20:35', NULL, 1),
(6, 'جام بالکن چیست و چه فوایدی دارد؟', 'جام-بالکن-چیست-و-چه-فوایدی-دارد؟', 'بالکن‌ها همیشه از قسمت‌های مورد علاقه‌ منازل بوده‌اند. این بخش از ساختمان در سال‌های اخیر به یکی از کاربردی‌ترین و اصلی‌ترین نقاط منزل تبدیل شده است؛ به…', 'بالکن‌ها همیشه از قسمت‌های مورد علاقه‌ منازل بوده‌اند. این بخش از ساختمان در سال‌های اخیر به یکی از کاربردی‌ترین و اصلی‌ترین نقاط منزل تبدیل شده است؛ به عبارت دیگر بالکن یکی از الحاقات ساختمان‌ها محسوب می‌شود که مساحت آن در مساحت آپارتمان و بنا محاسبه می‌گردد و در واقع فضاهایی مسقف هستند که حداقل یک طرف رو به فضای بیرونی دارند. گاهی بالکن‌ها دو طرف و گاهی سه طرف باز رو به فضای مجاور دارند. در این فضا قسمت‌های بسته شامل نیم دیوار، نرده یا ترکیب این دو با دیوار است در این بین افرادی هستند که به دنبال زیباتر کردن هر چه بیشتر نمای بیرونی ساختمان هستند. در این مقاله سعی داریم شما را با یکی از به‌روزترین سیستم‌های ساختمانی یعنی جام بالکن آشنا کنیم.\n\nسیستم جام بالکن برای اولین بار در سال ۱۹۸۱ در فنلاند طراحی و اجرا شد. پس از آن در سایر نقاط اروپا فراگیر شده و در سال ۲۰۰۷ وارد کشور عزیزمان ایران شد. می‌توان گفت یکی از مدرن‌ترین گزینه‌ها برای استفاده بهینه بالکن خانه سیستم جام بالکنی است که همانند یک پرده شیشه‌ای نمای خارجی بالکن را می‌پوشاند و امکان استفاده از بالکن را در چهار فصل سال امکان‌پذیر می‌سازد. این سیستم به دلیل اینکه همواره در تماس با فضای بیرون قرار دارد باید تمامی اجزاء و پروفیل‌های به کار رفته در آن در برابر عوامل بیرونی از مقاومت و استحکام کافی برخوردار باشند، خصوصا چرخ‌ها و دیگر قطعات داخل ریل حتما باید از جنس کروم و نیکل با روکش‌های مناسب الترامیدی تهیه شده باشند. ضدزنگ بودن اجزاء درگیر در سیستم نکته مهمی است که معمولا افراد سودجو از آن به‌راحتی رد می‌شوند و این مورد در طول سال‌های بعد مشتریان را به مشکلات عدیده دچار می‌کند.<h2><strong>جام بالکنی چیست؟</strong></h2>امروزه سیستم جام بالکنی برای بهره گیری بهتر از فضای بالکن های اماکن مسکونی، اداری یا تجاری به کار برده می شود. در این حالت قسمت باز بالکن به صورت متحرک محصور شده و امکان لذت بردن از مناظر زیبا را بدون آزار دیدن از هوای سرد و گرم و یا دیگر مشکلات محیطی فراهم کی شود. از آن گذشته این تکنولوژی علاوه بر محصور ساختن بالکن ها ، در فضاهای دیگری مانند فضاهای اداری، گلخانه ها، حاشیه استخرها و دیگر مکان ها قابل استفاده است.\n\nسیستم های جام بالکنی عمدتا با حرکت شیشه در ریل های آلومینیومی کار میکند و همه پنجره ها در گوشه مناسبی از بالکن جمع می شود، بنابراین آلومینیوم یکی از اجزای مهم در ساختار این گونه سیستم ها بوده و باید از استحکام و کیفیت خوبی برخوردار باشد تا جریان هوای بیرون و درون از یکدیگر مستقل باشند و انرژی داخل را حفظ کنند به طوری که عایق صوتی، حرارتی و رطوبتی با محیط بیرون ایجاد کرده و باعث صرفه جویی در مصرف انرژی شوند. در واقع انتخاب پروفیل مقاوم و استاندارد به نوبه خود یک عنصر مهم و بادوام در سیستم های جام بالکنی محسوب می شود.\n\nآلومینیوم به کار رفته در سیستم جام بالکنی متشکل از دو پروفیل افقی نصب شده روی ساختار های کف و سقف و همچنین دو پروفیل عمودی در دوطرف بالکن است. همچنین وزن سیستم 23 – 24 کیلوگرم در هر متر مربع است. سیستم حرکتی مورد استفاده در پانل ها به صورت لولایی است. این سیستم طوری طراحی شده که پانل اول ثابت بوده و بقیه پانل ها متحرک هستند و در ریل حرکت کرده و در انتها در کنار پانل ثابت قرار می گیرند. این سیستم ها این قابلیت را دارند تا با اضافه کردن آپشن هایی همچون پرده هایی کرکره ای و پلیسه ویژه این سیستم ، کاراریی و ظاهر خود را ارتقا ببخشیند<h2><strong>از فواید سیستم جام بالکنی باید به موارد زیر اشاره کرد</strong></h2><ul><li>به علت ماهیت خود هر زمانی که بخواهیم باز می شود، هر زمانی که بخواهیم بسته می شود و بالکن ها را تبدیل به مکان زندگی قابل استفاده و راحت می کند</li><li>با هماهنگی و تناسب با نما و معماری کلی سازمان، چشم اندازی زیبا به وجود می آورد</li><li>به علت قابلیت استفاده منعطف آن تحت شرایط باران برف و دیگر شرایط محیطی از بالکن به شیوه مطلوب خود استفاده کرد</li><li>از ورود سر و صدا گرد و غبار حشرات حیوانات و پرندگانی که میتوانند به بالکن ها وارد شوند جلوگیری می کند و بدین ترتیب فضای آنجا کاملا تحت کنترل است</li><li>با پروفیل ویژه ای که دارد باعث می شود تا جریان هوای بیرون و درون از یکدیگر مستقل باشند و انرژی داخل را حفظ می کند</li><li>با استفاده از شیشه های ویژه و به کار گیری سیستم های مغتاطیسی، عایق صوتی و حرارتی بسیار خوبی خواهند بود.</li></ul>\n    </div>', 'images/articles/3c818a66-283b-4454-bf71-1a2bc3f468bb.webp', 'جام بالکن چیست و چه فوایدی دارد؟', 'admin', '2021-10-11 12:57:31', 'published', 'جام بالکن چیست و چه فوایدی دارد؟', 'بالکن‌ها همیشه از قسمت‌های مورد علاقه‌ منازل بوده‌اند. این بخش از ساختمان در سال‌های اخیر به یکی از کاربردی‌ترین و اصلی‌ترین نقاط منزل تبدیل شده است؛ به…', '2026-08-20 19:48:48', '2026-09-06 13:20:35', NULL, 1),
(7, 'درب و پنجره باد بزنی چیست و برای نصب در چه مکان هایی مناسب است؟', 'درب-و-پنجره-باد-بزنی-چیست-و-برای-نصب-در-چ', 'در این درب و پنجره باد بزنی, پروفیل آلومینیوم لنگه بازشوی در آلومینیومی به وسیله لولاهایی خاص با پروفیل دماغه به چهارچوب متصل می گردد.', 'در صنعت آلومینیوم پیشرفت زیادی صورت گرفته است که سبب شده است درب و پنجره ها با مدل های مختلفی ساخته شوند که هر یک برای محیط های خاصی و شرایطی خاص کارایی داشته باشند. یکی از مدل هایی که در این نوشته قصد معرفی آن را داریم مدل باد بزنی است که هنگام تولید این مدل داشتن مقاومت و پایداری کاملا مورد توجه قرار گرفته است و ساخت آن به طریقی انجام می شود که درب و پنجره عمر بالایی داشته باشد.<h2><strong>درب و پنجره باد بزنی برای نصب در چه مکان هایی مناسب است؟</strong></h2>انواع بازشو باد بزنی یکی از مدل های جدیدی می باشد که به صورت رفت و برگشت باز می شوند و برای تکان دادن آن ها نیرویی کمی را لازم دارید که به آن ها وارد کنید. از این محصولات در هر مکانی می توانید استفاده کنید و برای نصب در هر بخشی مناسب هستند.\n\nبه صورت کلی نصب این مدل باد بزنی در قسمت هایی که سرعت و سهولت هنگام تردد بسیار مهم است، مناسب می باشد مانند مکان هایی عمومی مثل فروشگاه ها، بانک ها، رستوران ها و غیره. یکی از کاربرد های بسیار وسیع آن برای استفاده در بیمارستان ها است زیرا که سرعت در چنین قسمت هایی بسیار حائز اهمیت است.\n\nیکی دیگر از انواع در و پنجره آلومینیوم که کاربرد بسیار در فضاهای داخلی منازل یا اماکن پرتردد دارد ، درب بادبزنی یا در اصطلاح امریکایی آن درب کابویی است. این نوع از در آلومینیومی که در چند دهه گذشته در امریکا بسیار استقبال می شد, با پروفیل آلومینیوم نرمال به سهولت قابل تولید و استفاده است. در این نوع از در, پروفیل آلومینیوم لنگه بازشوی در به وسیله لولاهایی خاص با پروفیل دماغه به چهارچوب متصل می گردد.\n\nتفاوت این نوع از لولا در این است که قابلیت حرکت لنگه را در دو جهت داخل و خارج فراهم می نماید. استفاده از درهای بادبزنی ، در اماکن عمومی مانند بانک ، فروشگاه و رستوران که سرعت و سهولت در تردد و پارتیشن بندی های داخلی مد نظر است ، بسیار مورد استفاده است. به طور معمول این نوع از درهای آلومینیومی به گونه ای اجرا می گردد که طرف دیگر آن قابل دیدن باشد تا هنگام تردد دو نفر از روبرو به یکدیگر برخورد ننمایند. معمولا فضای بالا و پایین در بادبزنی باز و خالی ست و در غیر این صورت تمام شیشه خواهد بود.<h3><strong>ساخت درب و پنجره مدل باد بزنی به چه صورت است؟</strong></h3>در تولید این محصولات از<strong>پروفیل آلومینیوم</strong>استفاده شده است. لنگه باز شو را توسط لولا هایی ویژه به چهار چوب متصل می کنند و لولا در این انواع محصولات از مهم ترین بخش ها و قسمت ها است زیرا توسط آن باید بتوان لنگه را در دو جهت یعنی به سمت داخل و به سمت خارج حرکت داد و باید طراحی آن به صورتی باشد که سمت دیگر آن کاملا قابل دید باشد و دلیل آن این است که اشخاص هنگام تردد از طرفین به یک دیگر برخورد نکنند.', 'images/articles/درب و پنجره باد بزنی چیست و برای نصب در چه مکان هایی.webp', 'درب و پنجره باد بزنی چیست و برای نصب در چه مکان هایی مناسب است؟', 'admin', '2020-10-18 09:51:03', 'published', 'درب و پنجره باد بزنی چیست و برای نصب در چه مکان هایی مناسب است؟', 'در این درب و پنجره باد بزنی, پروفیل آلومینیوم لنگه بازشوی در آلومینیومی به وسیله لولاهایی خاص با پروفیل دماغه به چهارچوب متصل می گردد.', '2026-08-20 19:48:48', '2026-09-06 13:20:35', NULL, 1),
(8, 'ساب فریم یا فریم انتظار پنجره دوجداره upvc چیست و چه کارایی دارد؟', 'ساب-فریم-یا-فریم-انتظار-پنجره-دوجداره-upvc', 'استاندارد های ساب فریم سا فریم انتظار پنجره و نصب فریم آهنی پنجره در دیوار و قاب یا چارچوب فلزی پنجره وین تک و ویستا بست را اینجا مشاهده', '<h2>چرا باید از فریم انتظار پنجره استفاده کنیم؟</h2>فریم انتظار چارچوبی فلزی است که حدوده پنجره یو پی وی سی را تعیین می کند و بعنوان قاب در زیر پنجره و در داخل دیوار قرار می گیرد. معمولا زمان قرار دادن و نصب ساب فریم در پایان عملیات دیوارچینی و قبل از سفید کاری دیوار هست. بهتر است که قبل از زمان نصب، فریم انتظار رنگ آمیزی شود که در طول زمان دچار زنگ زدگی و خوردگی نشود.در هنگام نصب فریم انتظار باید به این نکته توجه کنید که فریم انتظار باید کاملا تر از، شاقول و همچنین بدون خمیدگی و پیچیدگی در محل مورد نظر نصب شود. در صورتی که ساب فریم کاملا تراز نباشد، در نصب پنجره دوجداره نیز اثر منفی می گذارد.فریم انتظار طوری باید نصب شود که در ادامه، مراحل بنایی باعث حرکت احتمالی آن نشود. همچنین طوری باید نصب شود که سطح داخلی فریم انتظار یا ساب فریم، با سطح کف دیوار ها مماس باشد. در شکل زیر مفهوم مماس بودن این دو را نمایش می دهیم.<h2>نکات مهم که برای نصب فریم آهنی پنجره باید در نظر گرفت:</h2><ul><li>استاندارد و متناسب با ابعاد و سطح مقطع پروفیل باشد.</li><li>برای نمای زیباتر در هنگام نصب ساب فریم یا فریم انتظار پنجره دوجداره در طبقاتی که نیاز به حفاظ ندارند، بهتر است دیواره ی بیرونی فریم انتظار با نما پوشش داده شود.</li><li>برای ممانعت از تاب برداشتن فریم آهنی انتظار در ابعاد بزرگ باید از تسمه آهنی در محیط های نمایش داده شده استفاده کرد تا از تاب دیدگی ممانعت کند.</li></ul><h2>استفاده از سنگ و سیمان بجای فریم آهنی انتظار</h2>در برخی از پروژه ها به جای بکارگیری از فریم آهنی پنجره، از سنگ و یا سیمان استفاده می شود و قاب پنجره را با این دو مصالح ایجاد می شود. به علت تراز نبودن، اختلاف عرض و ارتفاع اولیه و انتهایی چارچوب و احتمال انتقال بار دیواره ها به درب و پنجره دوجداره بهتر است از چارچوب آهنی استفاده کنید.<h2>ابعاد فریم انتظار و چارچوب فلزی پنجره به چه شکل است؟</h2>ابعاد قوطی آهنی مورد استفاده در فریم انتظار از ابعاد 30 در 60 (30*60 میلیمتر) شروع می شود. معمولا از قوطی 40 در 60 و یا کمتر نیز استفاده می شود که بسته به شرایط و عرض سطحپروفیل پنجره دوجداره یو پی وی سیدارد.بدلیل اینکه عمده برندهای پروفیل، از سری 60 یا 6 سانتی متری استفاده می کنند (همانن پنجره وین تکیپنجره ویستابست، قسمت 6 سانتی متری قاب فلزی انتظار باید رو به بالا قرار گیرد.پس از اتمام گچ کاری و تقریبا اتمام نما (با توجه به شرایط) می توان اقدام به نصب درب و پنجره دوجداره نمود. بعد از قرار گیری پنجره Upvc بر روی فریم انتظار،پروفیل Upvc به قوطی آهنی پیچ می شود و حداقل 2 سانتی متر در آهن فرو می رود.<h2>محل قرار دادن فریم انتظار در دیوار کجاست؟</h2>اینکه چارچوب آهنی قاب، لب به لب دیوار داخلی و یا در مابین نمای خارجی و داخلی گذاشته شود کاملا با نظر معمار و مهندس ساختمان صورت می گیرد. ولی باید دقت شود در حالتی که فریم انتظار مماس نمای دیوار داخلی قرار گیرد، باید جهت پوشاندن قاب فلزی از پروفیل لبه دار و یا قاب دور پنجره و رکوب چوبی استفاده کنید.\n    </div>\n    <div>', 'images/articles/ساب فریم یا فریم انتظار پنجره دوجداره.webp', 'ساب فریم یا فریم انتظار پنجره دوجداره upvc چیست و چه کارایی دارد؟', 'admin', '2020-09-07 08:01:21', 'published', 'ساب فریم یا فریم انتظار پنجره دوجداره upvc چیست و چه کارایی دارد؟', 'استاندارد های ساب فریم سا فریم انتظار پنجره و نصب فریم آهنی پنجره در دیوار و قاب یا چارچوب فلزی پنجره وین تک و ویستا بست را اینجا مشاهده', '2026-08-20 19:48:48', '2026-09-06 13:20:35', NULL, 1),
(9, 'سقف های شیشه ای یا skylight برای خانه، تراس، حیاط خلوت، پاسیو و استانداردهایش', 'سقف-های-شیشه-ای-یا-skylight-برای-خانه،-تراس،-حی', 'با توجه به پیشرفت روز افزون صنعت آلومینیوم و تلفیق مهندسی سازه با این صنعت و دستاوردهای جدید تکنولوژیکی در تولید اقلام و اتصالات، محصول آلومینیومی (در و…', 'با توجه به پیشرفت روز افزون صنعت آلومینیوم و تلفیق مهندسی سازه با این صنعت و دستاوردهای جدید تکنولوژیکی در تولید اقلام و اتصالات، محصول آلومینیومی (در و پنجره نما) با ضریب اطمینان قابل قبولی در اختیار مصرف کنندگان، کارفرمایان و معماران بناها قرار گرفته است. اجرای جداره‏‌های نورگذر در سقف‏‌ها و تلفیق این نوع فضاها با سازه‏‌های اصلی بنا امروزه در دستور کار معماران با تجربه و معماران جوان قرار گرفته است. در این گفتار سعی خواهیم کرد اشاره‏ای به این مبحث داشته باشیم. امروزه و به صورت مستمر اخبار متعددی در خصوص تولید شیشه‏‌هایی با قابلیت‏‌های فنی بالا در اختیار ما قرار می‏‌گیرد. بهبود مولفه‏‌هایی از جمله: و امکان تولید شیشه‏‌های لمینیت، نشکن و مقاوم در برابر ضربه، امکان استفاده وسیع شیشه را به راحتی فراهم ساخته است؛ حتی در سقف بناها. اما جهت نگهداری این شیشه‌‏ها مطمئنا به محصول دیگری نیز نیاز داریم که تمام وظایف یک سقف استاندارد را نیز داشته باشد. Sky light‏های آلومینیومی در این خصوص راه‌گشای بسیار مناسبی هستند. در مکان‏‌هایی که جهت پوشانیدن سقف از سازه فضایی استفاده می‌‏شود، جهت پوشانیدن این‏گونه فضاها از سازه‏های Sky light استفاده می‏ گردد. در فضاهایی مانند گنبدها و طاق‏‌ها نیز می‌‏توان ازسیستم‏های Sky light به راحتی بهره گرفت. با کمتر شدن فضاهای سبز در شهرها ساخت ساختمان‏‌های اکولوژیکی، در ساخت و سازهای شهری نمود بسیار بیشتری پیدا کرده است. با افزایش ارتفاع و دوری از فضاهای سبز برای واحدهایی که در این ارتفاع قرار می گیرند ایجاد تراس‏‌هایی که بتوان در آنها از فضای سبز استفاده کرد، امری لازم به نظر می‏‌رسد. Sky light‏ها در این خصوص نیز به کمک تکنولوژی آمده و تراس‌‏هایی با این ویژگی را می‏‌توان با کمک آنها ایجاد کرد. البته این سازه‏‌ها به جز ایجاد فضاهایی دلپذیر در داخل بناها زیبایی دو چندانی نیز از لحاظ استاتیکی به سازه بنا می‌‏بخشد. در طراحی سقف‏ها (این‏گونه پوشش‌‏ها) عواملی موثر وجود دارند، از جمله: 1. فاکتورهای بیرونی؛ 2. فاکتور معماری و فرهنگ بومی؛ 3. نوع سازه و کاربری بنا؛ 4. نوع معماری بنا ویا نوع جریان روح معماری بنا؛ 5. امکان استفاده از مصالح مطابق استاندارد (سقف‏های شیشه‏‌ای محاسبه شده و استاندارد)؛ 6. رعایت مقررات ملی ساختمان. سقف‏‌ها یکی از قسمت‌‏های جدانشدنی یک ساختمان می‌‏باشند، چه از لحاظ سازه‌‏ای چه از لحاظ زیبایی، ایستایی، آب بندی و هوابندی، مقاومت حرارتی و... ، البته از لحاظ سازه‏‌ای و محاسبات مهندسی نیز بسیار حساس و مهم می‏‌باشند. با استفاده از سازه‌‏های Sky light در بناهایی که درحال ساخت هستند (البته با رعایت اصول معماری، بومی و فرهنگی، سازه‏ای، منطقه‌‏ای) سقف‏‌هایی زیبا و امن را می‏‌توان در بناهایی از جمله مراکز تجاری، علمی و آموزشی، مسکونی، اداری، و صنعتی وتجاری ایجاد کرد. می‏توان از این‏گونه سازه‏‌ها جهت هدایت بیشتر نور به داخل فضا و زیبایی معماری بنا بهره‌‏مند گردید. رعایت سر‏فصل‏‌های مهم از جمله‏، محاسبات زلزله باد برف و همچنین وزن شیشه‌‏ها همانند سیستم‏‌های رایج کرتین وال امری لازم و ضروری می باشد‏. اجرای حجم‌‏های وسیع با سطح نورگذر بزرگ به راحتی قابل محاسبه و اجرا می‌‏باشند. البته فاکتورهایی از جمله نوع سیستم انتخابی در خصوص Sky light، نحوه آب بندی (استفاده از چسب‏ هایی با استانداردهای لازم در این خصوص) و مجری با سابقه اجرایی و اطلاعات مهندسی با تجربه اجرایی، در این خصوص نقش موثر و سازنده ای را می تواند ایفا ‏کند. هم‌‏اکنون در کشور شرکت‌‏های معدودی هستند که (با رعایت فاکتورهای ذکر شده در بالا محاسبات سازه‏ایی Sky lightها در فضاهای وسیع به همراه سازه‌‏های فضایی) این سرویس‏‌ها را در اختیارکارفرمایان محترم قرار می‌‏دهند. شرکت‌‏هایی نیز با عدم اطلاعات مهندسی دقیق سعی در کپی‏‌برداری و اجرای کار به صورت کاملا تجاری با حذف مولفه‏‌های اساسی این‏گونه سیستم‌‏ها در تلاش هستند بخشی از این بازار جدید را در اختیار داشته باشند. لازم به ذکر است در این خصوص تست‏‌هایی نیز وجود دارد از جمله تست‏‌های  که میزان آب بندی و ایستایی سازه را آزمایش می‏‌کنند.\n    </div>', 'images/articles/سقف های شیشه ای یا skylight برای خانه، تراس، حیاط خلوت، پاسیو و استانداردهایش.webp', 'سقف های شیشه ای یا skylight برای خانه، تراس، حیاط خلوت، پاسیو و استانداردهایش', 'admin', '2021-09-04 16:03:02', 'published', 'سقف های شیشه ای یا skylight برای خانه، تراس، حیاط خلوت، پاسیو و استانداردهایش', 'با توجه به پیشرفت روز افزون صنعت آلومینیوم و تلفیق مهندسی سازه با این صنعت و دستاوردهای جدید تکنولوژیکی در تولید اقلام و اتصالات، محصول آلومینیومی (در و…', '2026-08-20 19:48:48', '2026-09-06 13:20:35', NULL, 1),
(10, 'شیشه های رفلکس و انواع آن', 'شیشه-های-رفلکس-و-انواع-آن', 'شیشه رفلکس شیشه رفلکس شیشه ای است که به عنوان یکی از شیشه های با تقاضا بالا در بازار شناخته شده می باشد تنوع رنگی و مزیت های موجود در شیشه رفلکس باعث شده…', '<h2>شیشه رفلکس</h2>شیشه رفلکس شیشه ای است که به عنوان یکی از شیشه های با تقاضا بالا در بازار شناخته شده می باشد تنوع رنگی و مزیت های موجود در شیشه رفلکس باعث شده است.\n\nاین شیشه به عنوان یکی از اولین انتخاب ها برای پنجره در نظر گرفته شود.البته این شیشه تنها در پنجره استفاده نمی شود در برخی از موارد از شیشه رفلکس برای بالکن استفاده می شود و حتی لقب شیشه رفلکس بالکن نیز به آن داده می شود.<div>شیشه رفلکس به عنوان یکی از شیشه های پرفروش از تنوع رنگی و مزیت های قابل توجهی برخوردار است، قیمت شیشه رفلکس دوجداره تنها در پنجره مطرح نمی شود، کاربرد آن برای بالکن خانه هم می باشد.</div><div><div><h3>اولین ویژگی مهم شیشه رفلکس</h3>در ساخت شیشه رفلکس از آلیاژ و فلزاتی استفاده می گردد که این فلزات و آلیاژ موجب تغییر در خواص شیشه می شوند و رنگ شیشه را تغییر داده و بر میزان بازتاب نور از شیشه تاثیر می گذارند. شیشه های رفلکس که تنوع زیادی در رنگ دارند به دلیل بازتاب نور در طول روز و حالت آیینه ای که ایجاد می کنند مانع از دید داخل منزل از بیرون در طول روز می شوند اما این حالت در طول شب برعکس می شود و شیشه ها در شب از داخل ساختمان حالت آیینه ای پیدا می نمایند\n\nشیشه رفلکس دوجداره از دولایه شیشه شفاف و رفلکس ساخته می‌شود. میزان نور و گرمایی که از این شیشه عبور می کند به ترتیب برابر ۶۱ و ۶۳ درصد است.\nاین شیشه مانند شیشه‌ رنگی دارای انواع مختلفی است که ضخامت فضای بین آنها بسته به نوع پروفیل به کار رفته تعیین می شود.\nاین نوع شیشه را در رنگ‌های مختلف ازجمله سبز، آبی، برنزی، نقره‌ای و طلایی وجود دارند. تفاوت این نوع شیشه با شیشه‌ رنگی در میزان رفلکس نور و دید از محیط داخل ساختمان در طول روز و شب است.\nشب ها شیشه از خارج شفاف و از داخل آینه مانند است. در انتخاب این نوع شیشه باید به محدودیت های آن مانند آینه ای بودن در شب از سمت داخل توجه داشته باشید.<h2>مزایا شیشه رفلکس</h2>۱-<strong>شیشه های رفلکس</strong>عدم دید ناظر بیرونی در روز می باشد یعنی حتی اگر پرده ها کنار باشد کسی نمی تواند از بیرون داخل را مشاهده کند.حفظ حریم داخلی خانه با استفاده از شیشه رفلکس.\n\n۲-شیشه رفلکس یکی دیگر از مزیت های شیشه های رفلکس بازتاب نور مستقیم خورشید و کاهش ورود گرمای تابستان به داخل است.\nدارای زیبایی بسیار بالایی می باشد\n\n۳-این نوع از شیشه های اشعه های رادیواکتیو را نیز دریافت میکنند\n\n۴-بازتاب نور در شیشه های رفلکس در تابستان هنگامی که آفتاب به صورت مستقیم به این شیشه برخورد کند بازتاب داده می شود و گرمای آفتاب به داخل محیط وار نمی شود.\n\n۵-تنوع بالا رنگی در شیشه های رفلکس<h2>معایب شیشه رفلکس</h2>از معایب بزرگ شیشه‌های رفلکس می‌توان به این مورد اشاره کرد که این شیشه‌ها باعث تاریک شدن فضاهای داخلی می‌شوند. توصیه می‌شود که اگر ساختمانی دارای نور طبیعی مناسبی نیست از شیشه‌های رفلکس در پنجره‌های آن استفاده نشود و یا از شیشه‌های رفلکس نقره‌ای و با خاصیت بازتاب دهندگی پایین استفاده شود. قیمت بالاتر شیشه‌های رفلکس در مقایسه با دیگر شیشه‌های شفاف هم می‌تواند از معایب آن در نظر گرفت. نا گفته نماند که استفاده از اکسید فلزات و اجرا فرایند رفلکس کردن شیشه هزینه بر است و بالا بودن قیمت آن نسبت به شیشه‌های شفاف طبیعی است. <h2><strong>موارد کاربرد شیشه رفلکس با توجه به ویژگی آنها</strong></h2>1.ایجاد ظاهر زیبا برای ساختمان را می‌توان دومین خصوصیت شیشه‌های رفلکس برشمرد، با توجه به این که رنگ‌بندی متنوعی دارند.\n\n2. ویژگی دیگر شیشه رفلکس همان‌طور که از نام آن هم مشخص است، بازتاب نور مستقیم آفتاب و کاستن از میزان گرمای ورودی به فضای داخلی ساختمان‌ها در تابستان است.\n\nاین نوع شیشه‌ها طیف‌های مختلفی از نور را بازتابش می‌کنند و از این طریق در میزان نور و انرژی مورد نیاز برای یک مکان خاص تأثیر می‌گذارند، در واقع همچون آینه عمل می‌کنند. بخشی از نور که از شیشه عبور می‌کند باعث می‌شود که فرد بیرون را به آسانی ببیند.\n\nاز طرفی چون نور داخل نسبت به نور خارج بسیار کم‌تر است و نور بسیار کمی می‌تواند به بیرون از پنجره برسد فردی که در بیرون هست نمی‌تواند داخل ساختمان را ببیند.\n\n3. شیشه‌های رفلکس میزان ورود اشعه رادیواکتیو و حرارت را کاهش می‌دهند.\n\nاین نوع شیشه‌ها با ویژگی تنظیم و کنترل دمایی مناسبی که دارا می باشند تأثیر بخاری و کولر را بیشتر می‌کنند. در واقع برای اتاق‌های رو به آفتاب بسیار مناسب‌اند.<strong><span>برای<a href="http://alwinco.ir/pricing">محاسبه آنلاین قیمت پنجره دوجداره upvc</a>به این لینک بروید.</span></strong><h2>انواع شیشه رفلکس</h2> به‌طورکلی شیشه‌های رفلکس در رنگ‌های شیشه‌های رفلکس سبز، طلایی، نقره‌ای یا سیلور، آبی، شرابی، برنزی، دودی و شیشه‌های رفلکس ترکیب چند رنگ تولید می‌شوند که آلیاژ مورد نظر و اشتهای بازار قیمت آن را تعیین می‌کنند. البته شیشه‌های رفلکس هم مانند شیشه‌های ساده در حالت‌های دوجداره، سه جداره، سکوریت و در هر ضخامت تولید و عرضه می‌شوند. برای ساخت شیشه‌های دوجداره یا سه جداره رفلکس، تنها جداره خارجی را از شیشه رفلکس ساخته و جداره داخلی را از شیشه‌های معمولی استفاده می‌کنند. شیشه‌های سکوریت هم می‌توانند پس از تولید در شرکت‌های تولید کننده شیشه رفلکس به رنگ و میزان رفلکس مورد نظر مشتری تبدیل شوند. <h3>شیشه رفلکس نقره‌ای</h3> شیشه دوجداره نقره‌ای نسبت به سایر شیشه‌های رفلکس از خاصیت رفلکتیو (بازتاب دهندگی) بیشتری برخوردار است و به همین دلیل هم با نام شیشه‌های رفلکس آینه‌ای شناخته شده و در بین تمامی شیشه‌های رفلکس مختلف محبوبیت بیشتر دارد. البته شیشه دوجداره نقره‌ای یا سوپر سیلور نوعی شیشه بین شیشه ساده و رفلکس است و بالاترین میزان انتقال نور را دارد. این ویژگی باعث می‌شود شیشه دوجداره سوپر سیلور در فضاهایی با نور کم عملکرد مناسبی داشته باشد. شیشه دوجداره نقره‌ای برای سنگ نمای سفید، کرمی روشن، طوسی و مشکی انتخاب مناسبی است. <h3>شیشه دوجداره نقره‌ای (سوپر سیلور)</h3> شیشه دوجداره نقره ای نسبت به سایر شیشه های رفلکس از خاصیت رفلکتیو بیشتری برخوردار هستند و به همین دلیل هم با نام شیشه های رفلکس آینه ای شناخته شده است.\nشیشه دوجداره نقره ای یا سوپر سیلور نوعی شیشه بین شیشه ساده و نوع رفلکس است و بالاترین میزان انتقال نور را به این نوع شیشه نسبت می دهند.\nاین مشخصه سبب می گردد شیشه دوجداره سوپر سیلور در فضاهایی با نور کم عملکرد مناسبی داشته باشد. دلیل این موضوع هدایت نور خورشید تا میزان ۱۰۰ درصد به فضای داخل ساختمان می باشد. <h3>شیشه رفلکس دودی</h3> طبق بررسی‌های انجام شده، شیشه‌های رفلکس دودی، طلایی و نقره‌ای در بین تمامی شیشه‌های رفلکس محبوبیت بیشتری دارند. شیشه‌های رفلکس دودی در این بین با انتقال نور کمتر از نقره‌ای در ساختمان‌های مسکونی، اداری و تجاری مدرنی محبوبیت دارند که میزان ورود نور آن‌ها بیشتر است و نیاز دارند که این مقدار نور را کنترل کرده و کمتر کنند. <h3>شیشه رفلکس طلایی</h3> در بین ساختمان‌های کلاسیک با نمای رومی شیشه‌های رفلکس طلایی با قاب طلایی تیره، قهوه‌ای یا پی‌وی‌سی طرح چوب می‌تواند زیبایی نمای کرم قهوه‌ای ساختمان را زیباتر جلوه دهد. از طرفی هم میزان نور ورودی را آنچنان کاهش نمی‌دهد و باعث تیره شدن فضای داخلی نمی‌شود.\n</div>\n  <div>\n    <br>', 'images/articles/شیشه های رفلکس و انواع آن.webp', 'شیشه های رفلکس و انواع آن', 'admin', '2021-01-19 09:01:38', 'published', 'شیشه های رفلکس و انواع آن', 'شیشه رفلکس شیشه رفلکس شیشه ای است که به عنوان یکی از شیشه های با تقاضا بالا در بازار شناخته شده می باشد تنوع رنگی و مزیت های موجود در شیشه رفلکس باعث شده…', '2026-08-20 19:48:48', '2026-09-06 13:20:35', NULL, 1),
(11, 'شیشه کم گسیل (Low-E) چیست و چگونه کار می کند؟', 'شیشه-کم-گسیل-low-e-چیست-و-چگونه-کار-می-کند؟', 'خرید و فروش شیشه های کنترل کننده انرژی و شیشه دوجداره کم گسیل یا شیشه Low-E چیست و چگونه عایق حرارتی است و کاربردش چیست؟', '<h3><strong>شیشه کم گسیل (شیشه Low-E) چیست و عملکرد آن چگونه است ؟</strong></h3>قبل از آن نیاز است که در خصوص تابش خورشید و طیفهای نور بیشتر بدانیم .<div><strong>امواج تابشی خورشید بر اساس طول موج به سه طیف اصلی تقسیم میگردد</strong><strong>۱-طیف ماوراءبنفش(UV) (UltraViolet):</strong>با طول موج ۳۰۰ الی ۳۸۰ نانومتر، که برای پوست و چشم انسان مضر بوده و همچنین باعث رنگ پریدگی (تغییر رنگ) اجسام و وسایل نیز میگردد.<strong>۲- طیف مرئی (قابل رویت ) :‌</strong>با طول موج بین ۳۸۰ تا ۷۸۰ نانومتر، که شامل همه طیف رنگ ها بوده و باعث دیده شدن اشیا میگردد.<strong>۳- طیف مادون قرمز (IR) (InfraRed) :</strong>با طول موج بیش از ۷۸۰ نانومتر، این طیف از تابش خورشیدی موجب انتقال حرارت به محیط میگردد. بعبارت دیگر امواج مادون قرمز امواج گرمازای خورشید هستند که با طول موج بلند منتشر میشود. در واقع حرارت خورشید بصورت امواج مادون قرمز ساطع میشود.', 'images/articles/شیشه کم گسیل (Low-E) چیست و چگونه کار می کند.webp', 'شیشه کم گسیل (Low-E) چیست و چگونه کار می کند؟', 'admin', '2021-01-20 09:38:41', 'published', 'شیشه کم گسیل (Low-E) چیست و چگونه کار می کند؟', 'خرید و فروش شیشه های کنترل کننده انرژی و شیشه دوجداره کم گسیل یا شیشه Low-E چیست و چگونه عایق حرارتی است و کاربردش چیست؟', '2026-08-20 19:48:48', '2026-09-06 13:20:35', NULL, 1),
(12, 'مزایای پنجره upvc و تاثیر آن در ساختمان', 'مزایای-پنجره-upvc-و-تاثیر-آن-در-ساختمان', 'مزایای پنجره یو پی وی سی پنجره های UPVC از پروفیل های سخت و بادوام و از ماده UPVC ساخته می شوند. شکل مقطع چند حفره ای پروفیل های یو پی وی سی سبب مقاومت…', '<h2>مزایای پنجره یو پی وی سی</h2>پنجره های UPVC از پروفیل های سخت و بادوام و از ماده UPVC ساخته می شوند. شکل مقطع چند حفره ای پروفیل های یو پی وی سی سبب مقاومت این پنجره ها در مقابل هدر رفتن گرما، سرما و تعریق می شود. UPVC در برابر گرما و سرمای خیلی زیاد تغییر شکل نمی دهد.<ul><li>1) ا<strong>ستحکام و ماندگاری:</strong>در و<strong>پنجره upvc</strong>بسیار محکم هستند و از این لحاظ با همتای فلزی خود در یک مرتبه قرار دارند.</li><li>۲)<strong>عدم نیاز به رنگ آمیزی و ثبات رنگ</strong>: پروفیل های upvc سفید هستند و در صورت بالا بودن کیفیت مواد اولیه از ثبات رنگی بالایی برخوردار هستند، زنگ نمی زنند و جلای آن ها تغییر نمی کند.</li><li>۳)<strong>تنوع رنگی بالا:</strong>پروفیل upvc به دو صورت رنگی می شود:</li><li>الف)<strong>استفاده از پوشش های لمینت بر روی upvc</strong>- در این روش پوشش لمینت با ماندگاری بالا روی پروفیل چسبانده می شود و معمولاً طرح دار است، مانند طرح چوب و....</li><li>ب)<strong>رنگ آمیزی ماده upvc</strong>- در این روش از رنگ مخصوصی برای رنگ آمیزی ماده upvc استفاده می شود.</li><li>۴)<strong>عایق بندی صدایی و گرمایی:</strong>یکی از دلایل رشد پنجره های upvc عایق کاری ساختمان است. میزان عایق بندی پنجره های Upvc به شیشه، نوع پروفیل، یراق آلات، نصب، فرایند تولید و مونتاژ، ماشین آلات مورد استفاده در خط تولید و نوع پروفیل گالوانیزه درون پنجره و ... بستگی دارد که در پروفیل های با کیفیت بالا و عالی و استفاده از شیشه های چند جداره این عایق کاری به بهترین حال انجام می پذیرد.</li><li>5)<strong>افزایش امنیت:</strong>در پنجره های upvc به علت وجود یراق آلات و چفت های جدید و امکان طراحی پروفیل های امنیتی، ایمنی پنجره چندین برابر شده است.</li><li>6)<strong>ساخت پنجره به تمام اشکال هندسی:</strong>به علت امکان تغییر شکل<strong>پروفیل upvc</strong>با استفاده از دستگاه، می توان آن را به همه اشکال در آورد و خم های دلخواه را در آن ایجاد کرد. بنابراین بدون هیچ مشکلی می توان پنجره را به تمام اشکال هندسی دلخواه تولید کرد.</li><li>7)<strong>شیشه های چندجداره:</strong>بیشترین اتلاف حرارتی از شیشه های پنجره صورت می پذیرد که در صورت استفاده از این شیشه ها و جلوگیری از اتلاف حرارتی، میزان صرفه جویی انرژی به نحو قابل ملاحظه ای افزایش می یابد.</li><li>8)<strong>تنوع بسیار بالا در بازشو ها:</strong>یراق آلات پنجره های upvc حالت های بسیاری برای باز شدن پنجره ها را فراهم می آورند. مانند پنجره های بازشو از کنار و بالا و انواع کشویی و ....</li><li>9)<strong>امکان استفاده از قفل های اتوماتیک:</strong>در در و پنجره های upvc می توان از قفل ها و یراق آلات الکترونیکی و کنترل از راه دور استفاده کرد. امکانی که در پنجره های قدیمی آهنی یا آلومینیومی ممکن نبود.</li><li>10)<strong>تعویض آسان با پنجره های قدیمی:</strong>پنجره های قدیمی را می توان بدون عملیات بنایی و یا به هم ریختن نما، به سادگی با پنجره های upvc تعویض کرد.</li></ul><h2>استفاده از پروفیل و متریال مورد استفاده در پنجره upvc اصل و با کیفیت</h2>متأسفانه امروزه پروفیل‌ و یراق آلات تقلبی فاقد استانداردهای لازم و تولیدات بی کیفیت زیرزمینی هم در برندهای خارجی و هم در برندهای داخلی بسیار دیده می شود. پروفیل‌های تقلبی مشکل عظیمی را به وجود آورده است. البته شناسایی این پروفیل‌ها برای تولید کنندگان درب و پنجره upvc کار دشواری نیست. لذا کارخانه ها بایستی با دقت در خرید پروفیل‌ها از منابع اصلی و مطمئن این خدمات را به مشتریان تضمین کرده و همواره از متریال اصلی استفاده نمایند.<h2>یراق آلات در کیفیت پنجره های یو پی وی سی چه تاثیری دارد :</h2>در بکارگیری یراق آلات در سیستم یو پی وی سی، انتخاب یراق آلات مناسب نقش مهمی داشته و در کیفیت محصول نهایی تأثیر مهمی دارد. همان‌طور که می دانید یراق آلات درب و پنجره های یو پی وی سی از حدود صد قطعه بهم پیوسته تشکیل شده است. اکثر این قطعات بر روی یکدیگر حرکت مکانیکی داشته و مجموعه ای مانند ماشین باز شونده را ایجاد می‌نماید. لذا در انتخاب برند مناسب و همچنین با در نظر گرفتن نوع بازشو ها و انتخاب یراق مناسب با توجه به نیاز، می‌تواند هم هزینه ها را کنترل نماید و هم طول عمر بیشتر یراق آلات موجب می گردد. بایستی در نظر داشت یراق مناسب همیشه متنوع‌ترین آن‌ها نیست. به طور مثال اگر بازشوی درب و یا پنجره ای نیازی به دو حالته ندارد، نبایستی از یراق دو حالته استفاده کرد .<h2>این پنجره ها در کنار اتوبان و مسیر های شلوغ تاثیری دارد؟</h2>زمانی که درب و پنجره دوجداره به صورت استاندارد و با کیفیت تولید شود در تمامی موارد و مناطق کاملاً تاثیر گذلر بوده و بخش زیادی از آلودگی صوتی و محیطی را می‌کاهد.ولی برای مهار بیشتر مناطقی که دارای آلودگی‌های محیطی و صوتی خاص هستند و همچنین فضاهای صنعتی می‌توان از پنجره های سه جداره بهره گرفت. چراکه این نوع پنجره ها دارای قابلیت چند برابر بوده و بسیار کاربردی تر می باشند.<h2>آیا می‌توان پروفیل‌ یو پی وی سی و خراب را اصلاح و یا تعویض کرد؟</h2>پروفیل یو پی وی سی بخش اعظمی از متریال پنجره دو جداره upvcرا تشکیل داده و چنانچه از نوع نامرغوب آن استفاده شود، محصول نهایی دچار مشکلات دائم از قبیل تغییر رنگ پروفیل، تغییر فرم و یا شکستگی می‌گردد و تعویض و یا ترمیم آن امکان پذیر و مقرون به صرفه نمی‌باشد. بنابراین در انتخاب پروفیل یو پی وی سی بایستی دقت لازم را به خرج دهیم تا بتوانیم از تمامی قابلیت و محسنات پنجره دوجداره برای مدت زمان نامحدود استفاده نماییم .<h2>آیا پنجره دوجداره upvc قادر به مهار آلودگی صوتی و حرارتی می‌باشد ؟</h2>بله این محصول در برابر آلودگی محیطی و صوتی بسیار کارا بوده و در صورت تولید و نصب صحیح می‌تواند تا ۸۰% از آلودگی صوتی و محیطی بکاهد.<h2>چنانچه پروفیل پنجره ها تغییر رنگ دهد، آیا می‌توان آن را ترمیم کرد؟</h2>تغییر رنگ پروفیل نامرغوب یکی از شایع ترین مشکلات این نوع پروفیل ها می‌باشد که در صورت بروز این مشکل کاری نمی‌توان انجام داد. مگر با رنگ دیگر که این نیز در محل پروژه کار دشوار و غیر استانداردی است و در نهایت نظر و کیفیت مورد نظر را تأمین نمی‌نماید.<h2>آیا می‌توان یراق درب و پنجره دو جداره UPVC را پس از نصب تعویض نمود؟</h2>تغییر یراق امکان پذیر است اما نه هر تغییری زیرا نوع بستن یراق آلات و جای پیچ آنها با یکدیگر متغییر است و از طرفی نصب یراق آلات در سیستم کارخانه آریس بصورت اتوماتیک و با دستگاه مخصوص یراق بند انجام می‌شود و تغییر آن در محل پروژه محدودیت‌هایی را ایجاد می‌نماید.<h2>آیا تغییر شکل پروفیل پنجره upvc و آلومینویم قابل ترمیم می‌باشد؟</h2>تغییر فرم پروفیل در دو حالت حادث می‌گردد. یا با استفاده از پروفیل نامرغوب و یا عدم استفاده از گالوانیزه داخل پروفیل، که در دو حالت پروفیل تغییر فرم داده قابل ترمیم نمی‌باشد .\n    </div>', 'images/articles/مزایای پنجره upvc و تاثیر آن در ساختمان .webp', 'مزایای پنجره upvc و تاثیر آن در ساختمان', 'admin', '2021-01-20 07:21:26', 'published', 'مزایای پنجره upvc و تاثیر آن در ساختمان', 'مزایای پنجره یو پی وی سی پنجره های UPVC از پروفیل های سخت و بادوام و از ماده UPVC ساخته می شوند. شکل مقطع چند حفره ای پروفیل های یو پی وی سی سبب مقاومت…', '2026-08-20 19:48:48', '2026-09-06 13:20:35', NULL, 1),
(13, 'معرفی پروفیل ترمال بریک و مزایای استفاده از پنجره‌های دوجداره ترمال بریک', 'معرفی-پروفیل-ترمال-بریک-و-مزایای-استفا', 'امروزه با توجه به افزایش مصرف انرژی و به دنبال آن افزایش قیمت انرژی‌های مختلف، اغلب مردم به دنبال عایق بندی بهینه خانه‌ها، ویلاها یا دفاتر کار خود هستند…', '<div>امروزه با توجه به افزایش مصرف انرژی و به دنبال آن افزایش قیمت انرژی‌های مختلف، اغلب مردم به دنبال عایق بندی بهینه خانه‌ها، ویلاها یا دفاتر کار خود هستند. معمولا بیشتر افراد در این شرایط به سراغ عایق‌بندی سقف و دیوار و استفاده از لعاب‌های دو و سه گانه می‌روند و در اغلب موارد از نمایه‌های پنجره غافل می‌شوند.\n\nعایق درون پنجره با نام شکست حرارتی نیز شناخته می‌شود و این شکست حرارتی یک مانع دائمی بین قاب‌های پنجره در داخل و خارج از ساختمان ایجاد و از اتلاف انرژی جلوگیری می‌کند. برای حل مشکل اتلاف انرژی، تولیدکنندگان درب و پنجره، عایقی را ارائه داده‌اند، که به عنوان یک سد عایق بین داخل و خارج از قاب پنجره قرار می‌گیرد. این عایق همان چیزی است، که ترمال بریک نامیده می‌شود و در درب و پنجره های ترمال بریک کاربرد دارد.<h2>ترمال بریک چیست؟</h2>ترمال بریک یا گرمابند، عایقی است که در سمت خارجی چارچوب سازه‌ها یا درب و پنجره قرار می‌گیرد. این عایق مانع از جابه‌جایی حرارت می‌شود و برای جدا کردن سازه‌هایی که هدایت حرارتی بالایی دارند مورد استفاده قرار می‌گیرد.\n\nآلومینیوم رسانای خوبی از گرما و سرما است و می‌‌تواند گرمای زیادی را از طریق پنجره و درب از دست بدهد، یا به دست آورد. مقاومت بالا و سختی زیاد آلومینیوم باعث شده است، که این فلز به عنوان ماده اولیه در ساخت درب و پنجره مورد استفاده قرار بگیرد. اما رسانا بودن زیاد آلومینیوم ایراد بزرگ این فلز برای استفاده از آن در ساخت درب و پنجره‌های آلومینیومی به حساب می‌آید.خود آلومینیوم به تنهایی عایق سرما و گرما نیست، ولی زمانی که تیغه پلی‌آمید عایق در بین پروفیل دوخته می‌شود، ارتباط جداره بیرونی با جداره داخلی قطع می‌شود و پروفیل آلومینیوم، تبدیل به عایق یا همان ترمال بریک می‌شود. به همین دلیل پنجره های ترمال بریک طراحی و به بازار عرضه شدند و تا حد زیادی ایراد پنجره‌های آلومینیومی را برطرف کردند.\n\nپنجره‌های ترمال بریک از فناوری‌های پیشرفته‌ای هستند، که برای افزایش بهره‌وری انرژی و عایق کاری نوین در ساختمان ها مورد استفاده قرار می‌گیرند. پنجره‌های آلومینیومی ترمال بریک، پنجره‌هایی هستند که در ساخت ‌آن‌ها از دو فریم آلومینیومی استفاده شده است. این پنجره‌‌ها دارای یک مانع بین قسمت‍‌های داخلی و خارجی هستند، تا از هدر رفتن انرژی حرارتی از طریق آلومینیوم جلوگیری کنند.\n\nطبق تعریف رسمی انجمن ملی رتبه‌بندی پنجره، پنجره ترمال بریک را می‌توان به عنوان پنجره‌ای شناخت که در آن، قاب و اعضای بازشوی پنجره به عناصر خارجی و داخلی تقسیم می‌شوند و توسط متریالی که هدایت حرارتی را کاهش می‌دهند به هم متصل هستند.\n\nپنجره‌های آلومینیومی ترمال بریک با کاهش و کنترل انتقال حرارت یک راه حل سبز برای جلوگیری از هدر رفتن انرژی در منازل هستند. عملکرد عایقی خوب در پنجره‌های ترمال بریک باعث شده است تا این نوع از پنجره‌ها گزینه مناسبی برای بهینه سازی مصرف انرژی در ساختمان‌های تجاری و مسکونی به حساب آیند.\n\nنکته مهم در تولید پنجره‌های ترمال بریک، این است که حتما از جنس پلی‌آمید جهت عایق کردن پنجره استفاده شده باشد و از مواد دیگری مانند pvc استفاده نشود، زیرا این مواد مقاومت پنجره را کاهش می‌دهند. ترمال بریک به خاطر لاستیک پلی‌آمیدی که در بین جداره‌های داخلی و خارجی آن قرار دارد و توسط ماشین‌آلات پانچ می‌شود، از ورود گرما، سرما، صدا و لرزش به داخل ساختمان جلوگیری می‌کند.\n\nتیغه‌های پلی‌آمید موجود در پروفیل‌های آلومینیومی پنجره‌های دو جداره باعث می‌شود، تا ضریب انتقال حرارت آلومینیوم از ۲۰۳ به کمتر از ۴ کاهش پیدا کند. در واقع پلی‌آمید سبب قطع رسانایی در آلیاژ آلومینیوم می‌شود. مشخصات پروفیل، شکل و نحوه قرارگیری پلی‌آمید در تعیین این اعداد بسیار مهم و ضروری هستند.\n\nبهترین روش برای دانستن اینکه تیغه‌های استفاده شده در ترمال بریک کردن پنجره‌ها از نوع پلی‌آمید است یا خیر، آن است که تیغه‌ها را در معرض شعله مستقیم قرار دهید. در صورتی که تیغه مشتعل شود و بوی نایلون دهد، تیغه از نوع پی وی سی است و در غیر این صورت به احتمال زیاد تیغه از نوع پلی‌آمید و مرغوب است.\n\nدر سیستم‌های درب و پنجره ترمال بریک از ۲۰۰ طیف رنگی مختلف استفاده می‌شود. رنگ‌های پودری الکترواستاتیک، آنادایز و طرح چوب، سه رنگ پایه و اصلی سیستم‌های ترمال بریک را تشکیل می‌دهند. پنجره‌های آلومینیومی ترمال بریک آنادایز شده، در مقایسه با پنجره‌های یو پی وی سی دکورال و رنگی، برای مناطق گرم، خشک و گرمسیری از نظر مقاومت و ماندگاری رنگ و کیفیت، عملکرد بهتری از خودشان نشان می‌دهند.<h2>مزایای استفاده از پنجره‌های دوجداره ترمال بریک</h2>پنجره‌های دوجداره ترمال بریک، نویز، حرارت و سر و صدا را حدود صد برابر کمتر از پنجره‌های معمولی آلومینیومی انتقال می‌دهند. در پنجره‌های دوجداره ترمال بریک یک لایه اضافی تعبیه شده است که امنیت داخل ساختمان را تا چند برابر افزایش می‌دهد، همین طور این پنجره‌ها در برابر انتقال حرارت و اشتغال بسیار مقاوم هستند.\n\nپنجره‌های دوجداره ترمال بریک طول عمر و دوام بالایی دارند و کمتر دچار فرسایش و خوردگی می‌شوند، از این رو به هزینه تعمیر و نگهداری بالایی نیاز ندارند. استفاده از درب و پنجره‌های ترمال بریک باعث ۳۸ درصد کاهش اتلاف انرژی حرارتی در زمستان، ۳۲ درصد کاهش اتلاف انرژی در تابستان، ۲۸ درصد کاهش مصرف سوخت و ۲۰ درصد کاهش هزینه‌های سرمایه‌گذاری اولیه تاسیسات می‌شود.\n\nجنس خوب و شیوه ساخت‌ پنجره‌های ترمال بریک باعث شده است، که این پنجره‌ها برای مناطق زلزله‌خیز کاربردهای فراوانی داشته باشند. پنجره‌های دوجداره ترمال بریک دارای ساختار انعطاف‌پذیر و خوبی هستند و این انعطاف پذیری در قسمت‌های داخلی و خارجی پنجره کاملا نمایان است.\n\nیکی دیگر از مزیت‌های پنجره ترمال بریک این است، که قسمت‌های داخلی و خارجی می‌توانند رنگ‌های متفاوتی داشته باشد و با توجه به شرایط خاص پروژه می‌توان از پنجره با رنگ‌های متنوع استفاده کرد.\n\nاگر قصد خرید پنجره مناسب برای ساختمان مسکونی یا تجاری را دارید، ممکن است بین پنجره‌های یو پی وی سی و پنجره‌های آلومینیومی ترمال بریک که به شکلی خاص طراحی شده‌اند، مردد باشید. پنجره‌های ترمال بریک در مقایسه با انواع دیگر، در برابر عوامل جوی مختلف و کاهش مصرف انرژی برتر هستند.\n\nبا این وجود سایر انواع پنجره‌ها، هنوز هم محبوبیت خود را دارند و مورد استفاده قرار می‌گیرند و در شرایط متفاوت هر دو نوع این پنجره‌ها می‌توانند کاربردی و مقرون به صرفه باشند.</div><strong>مقالات پیشنهادی</strong><a href="https://alwinco.ir/%d9%86%d8%ad%d9%88%d9%87-%d9%85%d8%ad%d8%a7%d8%b3%d8%a8%d9%87-%d9%82%db%8c%d9%85%d8%aa-%d9%be%d9%86%d8%ac%d8%b1%d9%87-upvc/">نحوه محاسبه قیمت پنجره upvc</a>\n    </div>', 'images/articles/معرفی پروفیل ترمال بریک و مزایای استفاده از پنجره‌های دوجداره ترمال بریک جنریت.jpeg', 'معرفی پروفیل ترمال بریک و مزایای استفاده از پنجره‌های دوجداره ترمال بریک', 'admin', '2021-04-04 11:20:33', 'published', 'معرفی پروفیل ترمال بریک و مزایای استفاده از پنجره‌های دوجداره ترمال بریک', 'امروزه با توجه به افزایش مصرف انرژی و به دنبال آن افزایش قیمت انرژی‌های مختلف، اغلب مردم به دنبال عایق بندی بهینه خانه‌ها، ویلاها یا دفاتر کار خود هستند…', '2026-08-20 19:48:48', '2026-09-06 13:20:35', NULL, 1),
(14, 'مقایسه پنجره دوجداره لولایی با مدل کشویی از لحاظ عایق', 'مقایسه-پنجره-دوجداره-لولایی-با-مدل-کشو', 'چرا پنجره دوجداره لولایی عایق تر از مدل کشویی می باشد؟ معایب پنجره دوجداره ریلی چیست؟ تفاوت میان پنجره دوجداره کشویی و لولایی چیست؟', 'همانطور که می دانید<strong>پنجره دوجداره</strong>ریلی وقتی باز می شود فضایی را اشغال نمی کند و همین حسن آن است که این نوع پنجره را به یکی از محبوب ترین انواع<strong>پنجره دوجداره</strong>تبدیل کرده است.\n\nاما این نوع پنجره عایق کمتری نسبت به مدل لولایی و سایر مدل ها دارد به طوری که تولید این نوع پنجره در اروپا کنار گذاشته شده است.<strong>پنجره دوجداره ریلی</strong>به هم با پروفیل upvc قابل تولید است و هم با پروفیل آلومینیوم ترمال بریک. بسته به اینکه ابعاد پنجره جقدر باشد می توان تعیین کرد که پنجره دوجداره با کدام متریال تولید گردد.<h3>پنجره دوجداره ریلی upvc:</h3>این مدل پنجره هم پنجره upvc مدل کشویی می باشد. اگر می خواهید<strong>پنجره upvc</strong>کشویی خرید نمایید حتما یراق آن را roto آلمان انتخاب نمایید، چون تحمل وزن غلطک های آن تا ۲۰۰ کیلوگرم هستند و از متریال مقاومی ساخته شده است. ارتفاع بیشتر از ۲/۱۰ تجاوز نکند و عرض هر لنگه بیشتر از ۱/۲۰ تجاوز نکند.<h3>پنجره دوجداره ریلی آلومینیومی:</h3>اگر از نظر هزینه مشکلی ندارید و پنجره ریلی را می پسندید، پیشنهاد می گردد که از پنجره ریلی آلومینیومی ترمال بریک استفاده نمایید چون پروفیل آلومینوم در کل مقاوم تر از upvc می باشد و در پنجره ریلی عملکرد بهتری را نسبت به upvc از خود نشان می دهد مخصوصا در زمان هایی که ارتفاع زیاد است و یا عرض لنگه بسیار کم و مهمتر از همه اینکه پنجره قرار است در طبقات بالای ۵ نصب گردد. در این طبقات فشار وارده از طرف باد بر پنجره زیاد است در نتیجه آلومینیوم مقاوم تر است.<h3>چگونه معایب پنجره دوجداره ریلی را برطرف کنیم؟</h3>۱- اگر پنجره ریلی می خواهید حتما از یراق roto آلمان استفاده کنید.\n\n۲- ارتقاع پنجره خود را هرگز بالاتر از ۲/۱۰ در نظر نگیرید.\n\n۳- جهت ابعاد بزرگ از آلومینویم استفاده نمایید.\n\n۴-قسمت فیکس را هم بازشو مخفی بذارید تا امکان تمییز کردن هر دو شیشه مهیا گردد.\n    </div>', 'images/articles/مقایسه پنجره دوجداره لولایی با مدل کشویی از لحاظ عایق.webp', 'مقایسه پنجره دوجداره لولایی با مدل کشویی از لحاظ عایق', 'admin', '2020-11-16 06:10:48', 'published', 'مقایسه پنجره دوجداره لولایی با مدل کشویی از لحاظ عایق', 'چرا پنجره دوجداره لولایی عایق تر از مدل کشویی می باشد؟ معایب پنجره دوجداره ریلی چیست؟ تفاوت میان پنجره دوجداره کشویی و لولایی چیست؟', '2026-08-20 19:48:48', '2026-09-06 13:20:35', NULL, 1),
(15, 'نمای کرتین وال چیست و تفاوت اش با دیگر نماهای ساختمانی چیست؟', 'نمای-کرتین-وال-چیست-و-تفاوت-اش-با-دیگر-ن', 'نمای کرتین وال چیست؟ نمای لامل، یا همان نمای کرتین وال، یکی از سیستم‌های نمای مدرن ساختمانی است، که ساختاری خود ایستا دارد. ساختار خود ایستا، به ساختاری…', '<h2>نمای کرتین وال چیست؟</h2>نمای لامل، یا همان نمای کرتین وال، یکی از سیستم‌های نمای مدرن ساختمانی است، که ساختاری خود ایستا دارد. ساختار خود ایستا، به ساختاری گفته می‌شود، که سنگینی وزن بالای شیشه را بر روی سازه کرتین وال یا همان لامل‌ها و شاسی کشی‌های مربوطه نگه می‌دارد و هیچ گونه بار مرده‌ای را بر ساختمان تحمیل نمی‌کند.\n\nدر واقع نمای کرتین وال یا اصطلاحا لامل، نمایی شیشه‌ای است، که در صورت نصب شدن صحیح، سنگینی حاصل از وزن شیشه‌ها و بار انرژی‌های حاصل از باد، طوفان و بارندگی‌ها، معمولا متوجه پوسته خارجی نمای ساختمان می‌شود و متوجه خود ساختمان نخواهد بود.\n\nدر واقع، می‌توان گفت که سیستم نمای کرتین وال، یک سازه مجزا در ساختمان به شمار می‌رود. نمای کرتین وال با نام لاتین curtainwall، یکی از انواع نماهای شیشه‌ای ساختمان و بهترین نمای شیشه‌ای ساختمان از نظر مسائل سازه در ارتفاع به شمار می‌رود. در این نوع نما معمولا از مصالح سبک، به ویژه ترکیبات حاصل از آلومینیوم و شیشه استفاده می‌شود.\n\nدر واقع نمای کرتین وال جزء دسته‌بندی نماهای خشک و نماهای تهویه شونده به شمار می‌رود، که زیبایی خاصی نسبت به نسل قبل از خود دارد. نسل قبل از نمای کرتین وال، نمای فریم لس روی آهن نام داشت. در این نسل، با نصب سیستم فریم لس روی آهن، مشکلات متعددی از نظر آب بندی و هوابندی به وجود می‌آمد.\n\nمورد دیگری که بهتر است، درباره نمای کرتین وال بدانید، آن است، که استراکچر آلومینیومی لامل کرتین وال قابلیت نصبِ سایر متریال‌های پوششی از قبیل ورق آلومینیوم کامپوزیت نمای سرامیکی را با توجه به محاسبات سازه‌ای دارا است.\n\nپیش از پرداختن به هر گونه جزییات، باید تعریف درستی از نمای کرتین وال داشته باشیم. Curtain Wall اصطلاحی انگلیسی برای نوعی نما است، که معادل آن در فارسی، با عبارت دیوار پرده‌ای شناخته می‌شود.\n\nدیوار و پرده هر دو حائل‌ها و فاصله‌هایی بین دو فضا هستند، یکی از آن‌ها به عنوان فاصله‌ای سخت و سنگین و دیگری به عنوان حائلی سبک و قابل انعطاف شناخته می‌شود. از ترکیب این دو عبارت یا در حقیقت این دو نوع حائل، محققان به ترکیبی دست پیدا کرده‌اند که هم استحکام و مقاومت دیوار را دارد و هم زیبایی و سبکی پرده را دارا شده است.\n\nبه این ترتیب، نام انرا کرتین وال Curtain Wall برای این نوع نما انتخاب شده است. نماهای کرتین وال از آنجا که هیچ باری از خود ساختمان را به دوش نمی کشند و تنها نیروهایی که تحمل می‌کنند، نیروی وزن خودشان و همچنین نیروهای جانبی نظیر باد، باران و طوفان است، به همین دلیل،‌ سازه‌های خود ایستا نام گرفته‌اند.\n\nنمای کرتین وال، انواع و اقسام و زیادی دارد و پر کاربردترین آن‌ها که حتما شما هم زیاد در ساختمان‌های ساخته شده در کوچه‌ها و خیابان‌های اطراف محل زندگی‌تان دیده‌اید، نماهای کرتین وال شیشه‌ای هستند.\n\nاز ویژگی‌های مهم نمای کرتین وال، می توان به عایق حرارتی، رطوبت و صوتی بودن آن اشاره کرد. این ویژگی در نمای ساختمان، باعث بهینه سازی دمای محیط و نور می‌شود. به این ترتیب، مصرف انرژی‌های مختلف از جمله برق در ساختمان‌هایی که نمای کرتین وال دارند کاهش می‌یابد.\n\nاز سوی دیگر، از آنجایی که کرتین وال‌ها سازه‌هایی بسیار سبک هستند و بار کلی وارد بر ساختمان را کاهش می‌دهند، بنابراین مقاومت خوبی در برابر زلزله دارند. نصب نمای کرتین وال بسیار آسان‌تر از نصب سایر نماهای ساختمانی است. این نما همچنین زیبایی فراوانی دارد و از نظر قیمت، نسبت به سایر نماهای ساخمانی مقرون به صرفه‌تر است.\n\nاگر بخواهیم کمی فنی‌تر به تعریف نمای کرتین وال بپردازیم، کرتین وال‌ها در واقع شاسی‌ها و لامل‌هایی هستند، که در اطراف نمای پروژه ساختمانی قرار می‌گیرند. در این نوع نما، شیشه‌هایی که قرار است، به عنوان نمای ساختمانی نصب شوند، به جای اینکه روی خود ساختمان قرار بگیرند، روی سازه کرتین وال نصب می‌شوند.\n\nبه این ترتیب، وزن وارد شده حاصل از نصب شیشه‌ها بر ساختمان کاهش پیدا می‌کند. این کاهش وزن باعث می‌شود که مقاومت ساختمان نسبت به زلزله افزایش یابد. نماهای کرتین وال زیادی بر روی ساختمان‌های بزرگ و معروف شهر تهران نصب شده است، که با کمی دقت می‌توانید متوجه آن‌ها شوید.\n\nهمان طور که اشاره کردیم، ساختار اصلی و هسته کرتین وال یا استراکچر آن از شاسی و لامل تشکیل و سپس شیشه‌ها یا سایر پوشش‌ها بر روی آن‌ها با دقت و ظرافت نصب شده است.\n\nحالا حتما این سوال برای‌تان به وجود آمده است، که لامل چیست، لامل‌ها در واقع همان سازه آلومینیومی هستند، که شیشه‌های نما روی آن‌ها نصب می‌شوند. این لامل‌ها در دو جهت افقی و عمودی نصب می شوند و فضایی مشبک، مناسب با نصب صفحات شیشه ای یا غیره را ایجاد می‌کنند.\n\nبه لامل‌های عمودی مولیون و به لامل‌های افقی مربوط به نمای کرتین وال ترنسم می‌گویند. لامل‌ها نیز با توجه به طراحی نمای کرتین وال و کاربردی که دارند، دارا انواع مختلفی هستند. شناخته شده‌ترین انواع لامل‌ها، شامل لامل‌های آلومینیومی، لامل‌های فولادی و لامل‌های چوبی است. در حال حاضر، لامل آلومینیومی پر کاربردترین نوع لامل است.\n\nسطح مقطع لامل ها نیز به گونه‌ای توسط مهندسان طراحی شده است، که بتوانند لامل‌ها را با شیارهای مشخصی که بر روی آن‌های وجود دارد، در هم قفل کنند و یا هنگام نصب، شیشه‌ها در فضای بین مولیون و ترنسم قرار گیرند.\n\nهمچنین طراحی آن‌ها، به گونه‌ای است، که بتوان شیشه‌ها را با لاستیک‌های مخصوصی به نام EPDM در برابر نفوذ و هدر رفتن حرارت عایق بندی کرد. از این رو نماهای کرتین وال عایق صوتی، حرارتی و رطوبتی بسیار خوبی به شمار می‌روند.\n\nهمان طور که پیش از این گفتیم، لامل‌ها دارای انواع مختلفی همچون لامل‌های فولادی، چوبی و آلومینیومی هستند که بهترین نوع آن‌ها لامل آلومینیومی است. معمولا در اغلب پروژه‌های داخل کشورمان، مشاهده می‌کنیم که از لامل‌های آلومینیومی استفاده شده است.\n\nعلت استفاده از لامل‌های آلومینیومی، این است که نمونه‌های فولادی و چوبی به علت دارا بودن مشکل خوردگی و وزن بالا، باعث بروز مشکلاتی در عایق بندی می‌شوند. همین موضوع باعث شد، که این لامل‌ها خیلی زود از صحنه صنعت نمای ساختمانی حذف شوند.\n\nدر مقابل، نمونه آلومینیومی لامل‌های و آلیاژهای مشابه آن، به دلیل دارا بودن خواصی نظیر استحکام بالا در عین سبکی، توانایی جیگ و فیکسچر بودن بالا به منظور عایق بندی رطوبتی و هوادهی بیشتر مورد توجه قرار گرفته‌اند. همین مزیت‌‌های به ظاهر ساده، باعث شده است، که طراحان، معماران و مهندسان ساختمانی، علاقه بسیار زیادی به استفاده از نمای کرتین وال با لامل آلومینیومی داشته باشند.\n\nسیستم‌های مربوط به نمای کرتین وال، از نظر نصب نیز به دو نوع تقسیم بندی می شوند. نوع اول فریملس (framless) یا همان بدون نمایان شدن خطوط ظاهری نمایان نام دارد و نوع دوم به فیس کپ (facecap) یا در پوش دار معروف است.\n\nنمونه فریملس نماهای کرتین وال، خود به دو زیر مجموعه فول فریم (full frame) و یو فریم (Ufram) تقسیم‌بندی می‌شوند که هر کدام از این انواع با توجه به شرایط پروژه ساختار نما و سایر عوامل، توسط مهندسان و معماران حرفه‌ای انتخاب و پس از انجام کامل طراحی از نظر فنی و زیبایی شناختی در محل پروژه نصب می‌شوند.<h2>نمای کرتین وال چه تفاوتی با سایر نماها دارد؟</h2>یکی از سیستم‌های نمای مدرن ساختمانی، نمای کرتین وال است، که ساختاری کاملا جدا و مستحکم دارد. در واقع این نما به سبکی تولید و نصب می‌شود، که سنگینی زیاد شیشه‌های نما، وزن خود را بر روی سازه کرتین وال یا همان لامل‌ها و شاسی کشی‌های نما می‌اندازد.\n\nدر نتیجه هیچ بار مرده‌ای که حاصل از وزن شیشه‌ها و بار انرژی‌های حاصل از باد، طوفان یا زمین لرزه باشد، بر روی نما سنگینی نمی‌کند و هیچ تأثیری بر روی سازه ساختمان ندارد. در واقع می‌توان گفت،‌ که سیستم نمای لامل یا کرتین وال، یک سازه کاملا جدا از ساختمان به شمار می رود.\n\nاما سایر نماهایی مانند چوب، آجر یا سنگ اینگونه نیست و بر روی دیواره خارجی ساختمان نصب می‌شود. بنابراین ساختمان باید توانایی تحمل وزن این نماها را داشته باشد.\n\nدر مورد تفاوت میان نمای فریم لس و فیس کپ در نمای کرتین وال، باید دید بیرونی نما را در نظر گرفت. در نمای فیس کپ، المان‌های آلومینیومی عمودی و افقی نصب شده در نمای کرتین وال کاملا قابل مشاهده است و شیشه‌ها را ازهم متمایز می‌کند، ولی در نمای فریم لس، المان‌های آلومینیومی بیرونی حذف می‌شود و سازه‌های اصلی زیر شیشه‌های نمای فریم لس از بیرون ساختمان پنهان است. به این ترتیب، دید یک دست و زیباتری را به نمایش می‌گذارد.<h2>لامل چیست و چه ارتباطی با نمای کرتین وال دارد؟</h2>به استراکچر آلومینیومی نمای کرتین وال یا در واقع همان پروفیل‌های آلومینیومی که شیشه‌های نمای کرتین وال بر روی آن‌ها سوار می‌شوند، در اصطلاح فنی لامل گفته می‌شود.\n\nلازم است بدانید، که در نمای کرتین وال، لامل‌ها در دو بخش افقی و عمودی ارائه می‌شوند. همان‌طور که در ابتدای این مقاله گفتیم، لامل‌های افقی ترنسم و لامل‌های عمودی مولیون نامیده می‌شوند.\n\nلازم به ذکر است که در اجرای سیستم‌های مربوط به نمای کرتین وال، به طور معمول ترنسم یا لامل افقی در سایز طولی کوچک‌تری نسبت به مولیون یا لامل عمودی ارائه می‌شود. اما توجه داشته باشید، که با این وجود، عرض لامل‌ها باید با یکدیگر برابر باشند.\n\nوجود این اختلاف سایز در طول لامل‌ها به خاطر آن است، که بیشتر بار شیشه‌های نما بر روی لامل‌های عمودی یا مولیون‌ها خواهد بود، اما در افق دید، بعضی از طراحان، سازندگان ساختمان و آرشیتکت‌های معمار، به دلیل بالا رفتن سطح زیبایی بصری نما از داخل، اندازه طولی ترنسم و مولیون را با یکدیگر برابر در نظر می‌گیرند. البته این موضوع کاملا به ظرافت طراح و سازنده در طراحی نما و معماری بستگی دارد.\n\nلامل‌ها، از نظر برند و جنس متریال، انواع مختلفی دارند. لامل‌های در کشورهای مختلفی تولید می‌شوند، که یکی از کشورهای مهم تولید کننده این سازه‌ها، کشور آلمان است. این سازه‌ها از نظر جنس متریال به دسته‌های مختلف لامل آلومینیومی (Aluminium Curtainwall) لامل فولادی (Steel Curtainwall) و لامل چوبی (Timber Curtainwall) تقسیم بندی می‌شوند.<h2>عایق بندی در لامل نمای کرتین وال چگونه است؟</h2>نماهای دارای لامل به شیوه‌ای طراحی می‌شوند، که قابل عایق شدن در بهترین حالت ممکن باشند و از ساختمان در برابر نیروهای جوی و زیست محیطی مربوط به منطقه جغرافیایی‌شان محافظت کنند.\n\nبه همین دلیل در طراحی لامل‌هایی با مقاطع آلومینیومی، به صورت اصولی شیارهایی تعبیه شده است، که بتوان لاستیک‌های EPDM را برای اعمال ترمال بریک (Thermal Break) به سازه متصل کرد.\n\nبرای بالاتر رفتن سطح عایق‌بندی کار در برخی از سیستم‌های نمای ساختمانی کرتین وال، از لاستیک‌های پلی آمید نیز استفاده می‌شود و استفاده از ترمال بریک (Thermal Break) در هر سیستم کرتین وال، مختص به خود آن سیستم طراحی خواهد شد.\n\nبه طور مثال در سیستم نمای کاور کپ (Cover Cap) یا اصطلاحا درپوش دار، پلی آمید روی لامل قرار می‌گیرد، اما در سیستم فریم لس استپ یونیت (Full Frameless)، پلی آمید درون خود لامل‌ها جای‌گیری می‌شوند.\n\nدر واقع می‌توان گفت، که مراحل ساخت لامل‌ سیستم‌هایی که پلی آمید روی لامل قرار می‌گیرد یا درون لامل‌های جای‌گیری می‌شود، از سایر سیستم‌ها مجزا است. سیستم‌های نمای کرتین وال، که دارای لامل هستند، به دلیل شکل ظاهری و داشتن عایق‌های حرارتی از عایق‌بندی بالایی برخوردار هستند و نفوذ پذیری در این دسته از سیستم‌های مربوط به نمای ساختمان امکان پذیر نیست.\n    </div>', 'images/articles/نمای کرتین وال چیست و تفاوت اش با دیگر نماهای ساختمانی چیست.webp', 'نمای کرتین وال چیست و تفاوت اش با دیگر نماهای ساختمانی چیست؟', 'admin', '2021-04-04 10:57:11', 'published', 'نمای کرتین وال چیست و تفاوت اش با دیگر نماهای ساختمانی چیست؟', 'نمای کرتین وال چیست؟ نمای لامل، یا همان نمای کرتین وال، یکی از سیستم‌های نمای مدرن ساختمانی است، که ساختاری خود ایستا دارد. ساختار خود ایستا، به ساختاری…', '2026-08-20 19:48:48', '2026-09-06 13:20:35', NULL, 1),
(16, 'همه چیز درباره پروفیل آلومینیومی و درب و پنجره آلومینیومی دوجداره', 'همه-چیز-درباره-پروفیل-آلومینیومی-و-درب', 'بسیاری از ما، درب و پنجره‌های آلومینیومی قدیمی را به یاد داریم. این درب و پنجره‌ها، اولین نسل از درب و پنجره‌های غیرآهنی بودند، که عایق بهتری نسبت به…', 'بسیاری از ما، درب و پنجره‌های آلومینیومی قدیمی را به یاد داریم. این درب و پنجره‌ها، اولین نسل از درب و پنجره‌های غیرآهنی بودند، که عایق بهتری نسبت به پنجره‌های آهنی داشتند و به همین دلیل، پس از ورود به بازار، بسیار مورد استقبال مردم قرار گرفتند.\n\nدر سال‌های اخیر و پس از گذشت دهه‌ها، از ورود پروفیل‌های آلومینیومی به بازار درب و پنجره دوجداره، با پیشرفت تکنولوژی، درب و پنجره‌ دوجداره آلومینیومی جدیدی تولید می‌شوند.\n\nپروفیل‌های آلومینیومی، وقتی همراه با شیشه‌های دوجداره مورد استفاده قرار می‌گیرند، به صورت کامل عایق می‌شوند و دیگر سرما، گرما، گرد و غبار یا سر و صدا از آن‌ها نفوذ نمی‌کند.\n\nدر گذشته بیشتر درب و پنجره ها از آلومینیوم ساخته می شدند. آلومینیم به دلیل<span><i><b>رسانا بودن</b></i></span>موجب انتقال گرما و سرما در، درب و پنجره آلومینیومی می شد از این رو به منظور برطرف نمودن این مشکل درب و پنجره دوجداره آلومینیومی تولید و در بازار عرضه شد. در زمان های گذشته پنجره های آلومینیومی توسط میل گرد بهم وصل می شدند که امکان دوجداره نمودن آنها وجود نداشت، از این رو درب و پنجره های آلومینیومی از نوع اس تی را تولید کردند. در درب و پنجره آلومینیومی اس تی امکان دوجداره نمودن آنها وجود داشت ولی در اثر وجود درزهای موجود در آن معایبی ایجاد می شد. تولیدگنندگان به فکر تولید نوعی از درب و پنجره آلومینیومی افتادند که دارای عایق بندی مناسب بوده و معایب مدل اس تی را نداشته و همانند پنجره دوجداره دارای<span><i><b>عایق بندی</b></i></span>باشند.<h2>پروفیل آلومینیومی چیست؟</h2>از نظر لغوی، پروفیل به معنای ثابت بودن مقطع در طولی مشخص است. در دنیای فلزات و ساخت و ساز، پروفیل شامل انواع مختلفی است. اصلی‌ترین کاربرد پروفیل‌ها برای ساخت درب و پنجره‌های فلزی می‌باشد.\n\nآلومینیوم فلزی نقره‌ای رنگ با جلای فلزی، نرم، سبک و دارای قابلیت شکل‌پذیری زیاد است. از ویژگی‌های مهم آلومینیوم، سبک وزنی و قابلیت عدم زنگ‌زدگی می‌باشد. پروفیل اکستروژن آلومینیوم به عنوان یکی از پرمصرف‌ترین بخش مصارف آلومینیوم به حساب می آید.\n\nبرای تولید پروفیل آلومینیوم، ابتدا ماده اولیه را که بیلت آلومینیومی نام دارد، تحت فشار بسیار بالا و درجه حرارت مناسب قرار می‌دهند. سپس آن را از میان قالب های مخصوصی حرکت می‌دهند.\n\nبه این ترتیب ماده اولیه تغییر شکل پیدا می‌کند و به اشکال مورد نظر درمی‌آید. به خاطر اعمال فرآیند حرارتی و فشار بالا روی فلز آلومینیوم، ماده اولیه کاملا تغییرشکل پیدا می‌کند و در نتیجه پروفیل آلومینیوم تولید می‌شود.<h2>درب و پنجره آلومینیومی دوجداره چیست؟</h2>درب و ٖپنجره دوجداره آلومینیومی یا درب و پنجره‌های ساخته شده از پروفیل‌های آلومینیومی، نوعی از درب و پنجره‌ها هستند، که از گذشته تا زمان حال مورد استفاده قرار گرفته‌اند. در واقع درب و پنجره آلومینیومی یکی از انواع قدیمی پنجره‌ها به حساب می‌آید، که نسل اول آن در زمان گذشته طرفداران بسیاری داشته است.\n\nنسل اول درب و پنجره‌های آلومینیومی، با استفاده از میل‌گردهایی به هم متصل می‌شدند و امکان نداشت، که آن‌ها را تبدیل به درب و پنجره‌های دوجداره کرد.\n\nبه این ترتیب، برای بالا بردن کیفیت این جنس از درب و پنجره‌ها، نسل دوم آن‌ها که به درب و پنجره‌های اس تی معروف بود، تولید و وارد بازار شد. درب و پنجره‌های اس تی قابلیت دوجداره شدن را داشتند اما باز هم درزهایی در آن‌ها وجود داشت، که باعث می‌شد معایبی داشته باشند.\n\nمعایب درب و پنجره‌های آلومینیومی اس تی، به قدری بود، که دوجداره بودن آن‌ها را به چشم نمی‌آورد و باعث شد، که تولید کنندگان درب و پنجره‌ دو جداره آلومینیومی به فکر نوآوری جدید باشند.\n\nامروزه، تولید کنندگان با توجه به همه تجربیاتی که از گذشته تا کنون کسب کرده‌اند، درب و پنجره‌های آلومینیومی جدیدی را تولید کرده‌اند که جدیدترین پروفیل تولیدی در کشورمان هستند، که قیمتی بسیار مناسب و کیفیتی بسیار عالی و قابل قبول دارند.<h2>ویژگی‌های مثبت پنجره‌های آلومینیومی چیست؟</h2>پنجره‌ دوجداره آلومینیومی نسبت به سایر انواع پنجره‌ها برتری‌هایی دارد. پروفیل پنجره‌ دوجداره آلومینیومی مانند پنجره یو پی وی سی، شیمیایی نیستند و جزئی از طبیعت به حساب می‌آیند.\n\nآلومینیوم بدون شک قوی‌ترین فلز در دسترس امروز بر روی زمین است. پنجره‌های آلومینیومی قادر به نگهداری از پنل‌های شیشه‌ای بزرگ هستند.\n\nهمچنین پنجره‌هایی که از جنس پروفیل آلومینیوم تولید می‌شوند، با توجه به ویژگی مقاومت در برابر خوردگی‌شان، نیاز به تعمیر و نگهداری بسیار کمی بعد نصب دارند. این نوع پنجره‌های دارای طیف رنگی وسیع و متنوعی هستند و با هر سلیقه‌ای جور درمی‌آیند.\n\nبه علاوه، پروفیل پنجره آلومینیومی معمولا قوی و پایدار هستند و قادر به مقاومت در برابر شدیدترین عناصر و تغییرات جوی می‌باشند. این پنجره‌ها دارای انعطاف‌پذیری فراوانی هستند و می‌توان آن‌ها را برای پنجره‌هایی با ابعاد و اندازه‌های مختلف طراحی کرد. همین موضوع باعث محبوب شدن این پروفیل در بین معماران و طراحان ساختمان شده است.\n\nپروفیل‌های آلومینیومی برای پنجره‌ها، فریم‌های باریک‌تری در مقایسه با پروفیل‌های UPVC دارند و باعث می‌شوند نور بیشتری از پنجره به خانه وارد شود و این موضوع در زیباسازی و نورگیری فضای داخلی خانه موثر است.\n    </div>', 'images/articles/همه چیز درباره پروفیل آلومینیومی و درب و پنجره آلومینیومی دوجداره .webp', 'همه چیز درباره پروفیل آلومینیومی و درب و پنجره آلومینیومی دوجداره', 'admin', '2020-11-24 08:38:33', 'published', 'همه چیز درباره پروفیل آلومینیومی و درب و پنجره آلومینیومی دوجداره', 'بسیاری از ما، درب و پنجره‌های آلومینیومی قدیمی را به یاد داریم. این درب و پنجره‌ها، اولین نسل از درب و پنجره‌های غیرآهنی بودند، که عایق بهتری نسبت به…', '2026-08-20 19:48:48', '2026-09-06 13:20:35', NULL, 1),
(17, 'پروفیل های رنگی upvc پنجره دو جداره', 'پروفیل-های-رنگی-upvc-پنجره-دو-جداره', 'پنجره دوجدارهUPVC رنگی وین تک از طریق رنگ آمیزی یا لمینت کردن پروفیل های یو پی وی سی حاصل میشود که مزایای بسیار و قیمت مناسب و زیبایی دارد', '<h2>پروفیل های رنگی</h2>به طور کلی پروفیل های پنجره های دوجداره به صورت سفید تولید میشوند در بعضی از ساختمان های موجود مشاهده میشود که رنگ پنجره ها از سمت نما سفید نیست و به رنگهای مختلف در آمده و به دلیل حفظ رنگ پنجره ها به اجبار پروفیل ها باید رنگ بخورد تا نمای اصلی ساختمان ها حفظ شود و ترکیب ظاهری پنجره ها به هم نخورد.\nشرکت آلوین پنجره با استفاده از تجهیزات به روز بازار پنجره های یو پی وی سی را به صورت کاملا حرفه ای و با دقا تمام رنگ آمیزی کرده.رنگ پنجره های دوجداره نسبت به درخواست مشتری و با مشورت کارشناسان این شرکت زده میشود رنگهای پنجره تنوع زیادی داشته و محدودیتی در این باره وجود ندارد.<h2><strong>رنگ آمیزی یا لمینت پنجره دوجداره UPVC</strong></h2>شرکت ما در زمینه تولید درب و پنجره های دوجداره upvc خدمات ویژه ای ارائه می دهد.\n\nرنگ پروفیل پنجره upvc به صورت پیش فرض سفید می باشد اما رنگ پنجره های دوجداره upvc باید با طراحی نما هماهنگ باشد.\n\nازین رو شرکت ما مطابق با نیاز مشتریان پنجره های دوجداره upvc را با رنگ های انتخابی مشتریان تولید می کند.<ol><li>براساس آلبوم رال آلمان، مطابق با سلیقه مشتری تنوع رنگ ایجاد می شود.</li><li>تعویض و بازسازی پنجره upvc هر واحد و هماهنگی رنگ پنجره upvc جدید با سایر پنجره های قدیمی</li><li>پوشش رنگی دارای انعطاف پذیری و چسبندگی بالا است.</li><li>این نوع رنگ در مقابل خراشیدگی و ساییدگی مقاوم بوده، ریزش نداشته، ترک نمی خورد.</li><li>پنجره دوجداره upvc رنگی جایگزین مناسب برای پنجره آلومینیومی است.</li><li>در برابر شوینده و حلالهای آلی مقاوم است.</li><li>این نوع پنجره دارای رنگ متالیک و غیر متالیک با براقیت های براق، نیمه براق و مات است.</li><li>این نوع پنجره با طرح چوب در طیف های رنگی مختلف تولید می شود.</li><li>در برابر تابش مستقیم نور خورشید، اشعه ماورای بنفش و باران های اسیدی مقاوم است.</li></ol><h3><strong>پنجره دوجداره</strong><strong>UPVC</strong><strong>رنگی</strong></h3>پنجره دوجداره UPVC رنگی یکی از روش های مناسب برای زیبایی و جذابیت نمای داخلی و بیرونی خانه به شمار می رود و قیمت نصب و مزایای رنگ آمیزی پنجره دوجداره UPVC رنگی در بین سازندگان اهمیت دارد.\n\nپنجره رنگی با پروفیل UPVC و تولید قاب پنجره های دوجداره بسیار پرطرفدار است و جایگزین مناسبی برای پروفیل آلومینیومی است.\n\nهمچنین ضعف آلومینیوم در انتقال دما، موجب جایگزین شدن پروفیل UPVC به جای آلومینیوم شده و کاهش مصرف انرژی و هدر رفت گرما در ساختمان را موجب شده است.\n\nپروفیل UPVC خاصیت رنگ پذیری داشته و با استفاده از رنگ پاش می توان سطح آن را با طیف های مختلف رنگی پوشاند که این کار خاصیت ضد خش بودن را در پروفیل ایجاد خواهد کرد.\n\nپنجره رنگی با اشکال گوناگون، طرح ها و مدل های متفاوت برای سبک های مختلف کلاسیک و مدرن کاربرد داشته و این تنوع رنگ و فرم می تواند این نوع پنجره را با هر جنس و متریال یکپارچه با سایر پنجره ها و نمای قبلی ساختمان باشد.<div></div><div>\n    </div>\n    <br>', 'images/articles/پروفیل های رنگی upvc پنجره دو جداره.webp', 'پروفیل های رنگی upvc پنجره دو جداره', 'admin', '2020-09-04 11:23:09', 'published', 'پروفیل های رنگی upvc پنجره دو جداره', 'پنجره دوجدارهUPVC رنگی وین تک از طریق رنگ آمیزی یا لمینت کردن پروفیل های یو پی وی سی حاصل میشود که مزایای بسیار و قیمت مناسب و زیبایی دارد', '2026-08-20 19:48:48', '2026-09-06 13:20:35', NULL, 1),
(18, 'پنجره دوجداره با کرکره داخلی', 'پنجره-دوجداره-با-کرکره-داخلی', 'پنجره دوجداره UPVC که دارای پرده کرکره ای مابین شیشه ها می باشند.دردو نوع دستی و برقی موجود است. امکان تنظیم میزان نور ورودی را دارند', 'پنجره دوجداره با کرکره داخلی\n\nتوضیحات زیر در مورد پنجره دوجداره با کرکره داخلی یا شیشه دوجداره کرکره دار که قطعا می تواند به شما برای انتخاب یک مدل مناسب از این محصولات کمک کننده باشد.<strong>پرده کرکره بین دو شیشه</strong>امروزه کاربرد های زیادی دارند و در بسیاری از مکان ها مورد استفاده قرار می گیرند آنها دارای تنوع رنگی و محصولی مختلفی می باشند و می توانند حتی به دکوراسیون داخلی منزل و ادارت شما نیز کمک کننده باشند. برخی از این پرده کرکره ها در داخل از کشور و برخی دیگر در خارج از کشور تولید می شود که طبیعتا نمونه های خارجی دارای قیمت بیشتری می باشند که معمولا نیز از کشور ترکیه وارد ایران می شوند.<h2>پرده کرکره ای بین شیشه دوجداره چیست</h2>در واقع زمانی که بخواهیم دید محیط بیرونی را نسبت به محیط خارجی از بین ببریم می توانیم از شیشه های مات اسفاده نماییم اما این شیشه های مات به صورت کامل این کار را برای شما انجام می دهند به عبارت دیگر شما مجبور هستید همیشه قید نور دهی خارجی را بزنید البته یک راه وجود دارد و آن این است با استفاده از تعویض شیشه باز به حالت قبل شیشه را برگردانید اما مطمئنن این می تواند برای شما هزینه داشته باشد اما خوشبختانه امروزه با آمدن شیشه دوجداره کرکره دار یا همان پرده بین دو شیشه کار راحت تر شده است و شما می توانید تنها با یک اهرم که می تواند یک طناب یا ولوم باشد دید محیط داخلی و بیرونی را از بین ببرید و هر زمانی که خواستید نیز دوباره دید را به حالت قبل برگردانید.\n\nانواع شیشه دوجداره کرکره‌دار\n<figure class="article-figure">\n  <img src="../../images/articles/%D8%A7%D9%86%D9%88%D8%A7%D8%B9%20%D8%B4%DB%8C%D8%B4%D9%87%20%D8%AF%D9%88%D8%AC%D8%AF%D8%A7%D8%B1%D9%87.webp" alt="انواع شیشه دوجداره کرکره‌دار" width="960" height="540" loading="lazy" decoding="async">\n</figure>\n<h3>انواع شیشه دوجداره کرکره‌دار</h3><h4>شیشه دوجداره کرکره‌دار دستی</h4>این نوع از<strong>پرده داخل شیشه دوجداره</strong>به این صورت کار می کند که دارای یک ولوم در بدنه پنجره می باشد و به محیط حرکت دادن این ولوم عمل باز و بسته شدن در حد سایه و روشن انجام می گیرد این مدل از پرده کرکره بین دو شیشه در صورتی ولوم یا نخ دچار مشکل شود از کار افتاده و معمولا توجه به انتخاب این نوع از پرده بسیار مهم می باشد چرا که نعمیر و نگهداری آن نیز بسیار دشوار می باشد و شاید به صرف نیز نباشد<h4>شیشه دوجداره کرکره‌دار برقی</h4>یا نام دیگر آن پرده کرکره خودکار می باشد که این امکان را به شما می دهد که با استفاده از یک ریموت عمل باز و بسته شدن پرده را انجام دهید این شیشه دوجداره کرکره‌دار بسیار زیبا عمل می کند و نسبت به سایر نمونه های دیگر گران تر می باشد برای نصب و راه اندازی این نوع از کرکره داخل شیشه از یک موتور توبولار 24 واتی استفاده می شود<h3>خرید پنجره دوجداره با کرکره‌ داخلی</h3>در صورتی که نیاز به خرید و نصب این نوع از پرده داخل شیشه دوجداره دارید می توانید با شماره های مندرج در وب سایت با ما در تماس باشید تا همکاران ما به صورت کامل شما را راهنمایی نمایند.\n    </div>', 'images/articles/پنجره-دوجداره-با-کرکره-داخلی.webp', 'پنجره دوجداره با کرکره داخلی', 'admin2', '2022-08-31 18:11:53', 'published', 'پنجره دوجداره با کرکره داخلی', 'پنجره دوجداره UPVC که دارای پرده کرکره ای مابین شیشه ها می باشند.دردو نوع دستی و برقی موجود است. امکان تنظیم میزان نور ورودی را دارند', '2026-08-20 19:48:48', '2026-09-06 13:20:35', NULL, 1),
(19, 'پنجره دوجداره کشویی بهتر است یا لولایی؟ پنجره فولکس واگنی و برتری اش نسبت به این دو', 'پنجره-دوجداره-کشویی-بهتر-است-یا-لولایی', 'پنجره دوجداره کشویی بهتر است یا لولایی؟مزایا و معایبشان چیست؟ میدانستید پنجره فولکس واگنی مزایای پنجره کشویی و لولایی را داردند', 'همانطور که می‌دانید<strong>پنجره‌ دوجداره</strong>یکی از نیازهای اصلی هر ساختمانی است. امروزه پنجره‌های دوجداره مختلفی در بازار وجود دارد که افراد با توجه به نیاز خود اقدام به خرید هر یک از آن‌ها می‌کنند. هر یک از این پنجره‌ها ویژگی‌های خاص خود را دارند و از مزایا و معایب منحصر به فردی نیز برخوردار هستند. به نظر شما<strong>پنجره دوجداره کشویی بهتر است یا لولایی</strong>؟ این دو پنجره چه تفاوت‌هایی با هم دارند؟ این سوالات معمولا ذهن تمام خریداران پنجره را به خود مشغول می‌کند و پاسخ به آن‌ها از اهمیت بسیار بالایی برخوردار است. اگر شما هم قصد خرید پنجره را دارید اما درباره ویژگی‌های هر یک از آن‌ها اطلاعی ندارید، حتما تا انتهای این مقاله با ما همراه باشید.\n\nآشنایی با انواع پنجره دوجداره<h2>آشنایی با انواع پنجره دوجداره</h2><h3><strong>تفاوت بین پنجره کشویی و پنجره لولایی</strong></h3>اگر قصد خرید<strong>پنجره دوجداره</strong>را دارید، باید بدانید که این پنجره‌ها در انواع ومدل های مختلفی تولید میشوند، که متداولترین آنها دو نوع کشویی و لولایی می باشد. تفاوت این پنجره‌ها معمولا در قیمت نهایی ، کارایی و عایق بندی آن‌هاست. در واقع پنجره‌های لولایی از عایق بندی بهتری برخوردار هستند و در جلوگیری از اتلاف انرژی عملکرد بهتری دارند. همچنین خوب است بدانید که در هنگام باز و بسته شدن پنجره‌های لولایی اصطکاک کمتری میان لنگه و فریم وجود دارد. بنابراین این پنجره‌ها نسبت به نوع کشویی بهتر باز و بسته می‌شوند. انتخاب هر یک از این پنجره‌ها به سلیقه فردی، شرایط محیطی، متراژ فضا و بودجه شما بستگی دارد. بنابراین پیش از اقدام به تهیه پنجره کسب اطلاعات در این زمینه اهمیت بالایی دارد. برای آشنایی بیشتر و درک بهتر تفاوت‌ها به بررسی ویژگی‌ها، مزایا و معایب هر یک می‌پردازیم.<h3><strong>پنجره دوجداره</strong><strong>کشویی، مزایا و معایب آن</strong></h3>پنجره کشویی به پنجره ای گفته می‌شود که روی ریل باز وبسته می شود و در هنگام باز شدن هیچ فضایی را اشغال نمی‌کند. این مدل از<strong>پنجره دوجداره</strong>جز مدل‌های پرطرفدار است و امروزه افراد زیادی اقدام به خرید آن می‌کنند. پنجره‌های کشویی معمولا" پروفیلی دارند که پهنای این پروفیل تقریبا دو برابر پروفیل پنجره‌ی لولایی است و به همین دلیل ممکن است کمی حجیم تر از دیگر پنجره‌ها به نظر بیایند. این مدل مزایا و معایبی دارد که در ادامه مشاهده می‌کنید.<h3><strong>مزایای پنجره دوجداره کشویی</strong></h3><ol><li>این پنجره‌ها برای فضاهای کوچک و محدود بسیار مناسب هستند و به راحتی زیر پرده نیز باز می‌شوند، که مهترین مزیت این نوع پنجره می باشد.</li><li>پنجره‌های کشویی به راحتی باز و بسته شده، و به چپ یا راست کشیده می‌شوند. سر خوردن پنجره روی ریل بسیار سریع انجام می‌شود و هیچ فضای اضافی هم اشغال نمی‌کند.</li><li>این پنجره‌ها ظاهر بسیار زیبایی دارند و برای دکوراسیون داخلی گزینه بسیار مناسبی می‌باشند.</li></ol><h2>پنجره کشویی و مزایای آن</h2><h3><strong>معایب پنجره‌ دوجداره کشویی</strong></h3><ol><li>اگر بخواهید پنجره‌های کشویی را با لولایی مقایسه کنید باید بدانید که این پنجره‌ها بدلیل عدم امکان استفاده از لاستیک آبندی ،نسبت به پنجره‌های لولایی از عایق بندی کمتری در مقابل گرد و خاک، صدا و سرما برخوردار می باشند.</li><li>اگر روی نظافت پنجره‌های خود حساس هستید، باید بدانید که معمولا" در این مدل پنجره‌ها تنها یک قسمت از شیشه تمیز می‌شود و بخش دیگر آن قابل نظافت نیست. مگر اینکه شما از نمای ببرون به پنجره دسترسی داشته باشید.</li><li>برای اجرای پنجره‌های ریلی باید به عرض پنجره توجه داشته باشید. معمولا" برای اجرای پنجره‌های کشویی، عرض پنجره نباید از 100 سانتی متر کمتر باشد.</li><li>امکان استفاده از توری در بعضی از مدل های این پنجره‌ها وجود ندارد.</li><li>این پنجره‌ها اغلب پروفیل بازسازی ندارند.</li><li>در ساخت این پنجره‌ها بایستی از غلتک‌های باکیفیت استفاده شود زیرا وزن لنگه بازشو معمولا سنگین است و اگر غلتک باکیفیت نباشد، بازشو به سختی حرکت می‌کند.</li><li>اغلب پنجره‌های کشویی در هنگام وزش باد شدید زوزه می‌کشند.</li></ol><h3><strong>پنجره‌های لولایی و مزایا و معایب آن</strong></h3>این پنجره ها دارای لولا می‌باشند و یک لنگه از آن‌ها توسط دستگیره باز می‌شود. جهت باز شدن این پنجره‌ها معمولا از بغل و یا از بالا است. خوب است بدانید که مزایای پنجره‌های لولایی بیشتر از پنجره‌های کشویی است و ممکن است انتخاب مناسب‌تری باشند. در ادامه مزایا و معایب این پنجره‌های پرطرفدار را مشاهده می‌کنید.\n\n<h2>پنجره دوجداره لولایی</h2><h3><strong>مزایای پنجره‌ دوجداره لولایی</strong></h3><ol><li>پنجره‌های لولایی دارای لاستیک آبندی هستند و به همین دلیل عایق بندی بهتری نسبت به پنجره‌های کشویی دارند.</li><li>این پنجره‌ها برای هر عرض و ارتفاعی قابل اجرا می‌باشند و هیچ محدودیتی در این زمینه وجود ندارد.</li><li>معمولا" پنجره‌های لولایی نسبت به کشویی قیمت مناسب تری دارند.</li><li>برخی از این پنجره‌ها دو حالته می‌باشند که از بالا و هم راست یا چپ باز می‌شوند.</li><li>پنجره‌های لولایی عمر بالاتری دارند و ایمن‌تر می‌باشند.</li></ol><h3><strong>معایب پنجره‌ دوجداره لولایی</strong></h3><ol><li>در این مدل پنجره دوجداره لنگه‌ای که باز می‌شود معمولا فضایی را اشغال می‌کند که این اشغال فضا ممکن است در محوطه‌های کوچک مشکل ساز باشد.</li><li>در این پنجره‌ها معمولا لنگه‌ای که باز می‌شود سرگیر می باشد.</li><li>باز کردن پنجره‌های لولایی از زیر پرده‌ اندکی مشکل است.</li></ol><h3><strong>پنجره فولکس واگنی چیست؟</strong></h3>اگر نام<strong>پنجره دوجداره</strong>فولکس واگنی را شنیده باشید حتما می‌دانید که این مدل یکی از پرطرفدارترین پنجره های موجود در بازار است. این پنجره‌ها ظاهر بسیار زیبایی دارند و در عین حال از مزایای بسیار زیادی نیز برخوردار می‌باشند. این پنجره‌ها از لحاظ ظاهری شباهت بسیار زیادی به پنجره‌های کشویی دارند و نحوه باز شدن آن‌ها نیز به صورت ریلی است. همانطور که گفته شد پنجره‌های کشویی معایب نسبتا زیادی دارند و این معایب افراد زیادی را در خرید پنجره کشویی مردد کرده است. خوب است بدانید که پنجره فولکس واگنی معایب پنجره کشویی را جبران کرده است و می‌تواند جایگزین مناسبی برای آن باشد. لازم به ذکر است که در ساخت این پنجره‌ها از یراق آلات خاصی استفاده شده است که این یراق آلات اغلب جزء گران‌ترین یراق آلات موجود در بازار است. پنجره‌های فولکس واگنی معمولا به صورت تمام اتومات و نیمه اتومات قابل اجرا می‌باشند.\n\nپنجره فولکس واگنی<h2>پنجره فولکس واگنی</h2><h3><strong>مزایای پنجره دوجداره فولکس واگنی</strong></h3><ol><li>این پنجره به هنگام باز و بسته شدن هیچ فضایی را اشغال نمی‌کند و مزاحمتی نیز برای نصب انواع پرده ایجاد نخواهد کرد.</li><li>این مدل پنجره بدلیل مقاومت بالای یراق آلات تقریبا" در هر ابعادی قابل اجرا می باشد.</li><li>این پنجره‌ها عایق صد درصد حرارت و صدا می‌باشند. با نصب پنجره فولکس واگنی هیچ انرژی تلف نمی‌شود و آلودگی صوتی نیز ایجاد نخواهد شد.</li><li>همچنین این مدل<strong>پنجره دوجداره</strong>امکان باز شدن از بالا را نیز به شما می دهد.</li><li>این پنجره‌ها ظاهر جذابی دارند و نظر افراد زیادی را به خود جلب کرده است.</li></ol><em>بیشتر بدانید:<a href="https://alwinco.ir/%d9%be%d8%b1%d9%88%da%98%d9%87-%d9%be%d9%86%d8%ac%d8%b1%d9%87-%d9%81%d9%88%d9%84%da%a9%d8%b3-%d9%88%d8%a7%da%af%d9%86%db%8c/"></a></em><h3><strong>قیمت پنجره فولکس واگنی چقدر است؟</strong></h3>پروفیل استفاده شده در این مدل پنجره هیچ تفاوتی با پروفیل های لولایی ندارد و اختلاف بهای تمام شده، فقط بخاطر قیمت بالای یراق آلات فولکس واگنی می باشد.\nمشاهده ویدیو پنجره فولکس واگنی تولید شده یکی از مشتریان ما\nنوع یراق: همانطور که گفته شد این پنجره‌ها دردو نوع اتومات، نیمه اتومات قابل اجرا می‌باشند که در این میان پنجره فولکس واگنی اتومات بیشترین قیمت را دارد.\n\nابعاد: بدیهی است که هر چه ابعاد پنجره بزرگ تر باشد، قیمت تهیه و اجرای یراق آلات آن نیز بالاتر خواهد بود.\n\nکیفیت یراق: همچنین کشور سازنده یراق و نام برند تولید کننده آن بهتر باشد، تاثیر بسیار زیادی در قیمت پنجره دارد.\n\nنصب پنجره‌های دوجداره<strong>نتیجه گیری</strong>پس از مطالعه این مقاله ممکن است این سوال در ذهنتان ایجاد شود که کدام یک از پنجره‌های نام برده شده مناسب‌تر است؟ در واقع هر یک از این پنجره‌ها مزایا و معایب خاص خود را دارند و انتخاب و اجرای هر یک از پنجره‌ها به بودجه و نیازهای مخاطب بستگی دارد. به صورت کلی می‌توان بیان کرد که پنجره فولکس واگنی برترین پنجره از لحاظ ویژگی‌ها، کیفیت و ظاهر است. این پنجره ممکن است نسبت به دو پنجره دیگر قیمت بالاتری داشته باشد بنابراین انتخاب آن ارتباط مستقیم با بودجه شما دارد. در پایان باید بدانید که پنجره فولکس واگنی تمام مزایای پنجره‌های لولایی و کشویی را دارد و جایگزین مناسبی برای هر دو آن‌ها می‌باشد. برای اطلاع از قیمت انواع پنجره‌های فولکس واگنی، لولایی و کشویی می‌توانید با کارشناسان ما ارتباط برقرار کنید.\n\n<br><em>بیشتر بدانید:<a href="http://alwinco.ir/pricing">مشاهده نرم افزار محاسبه آنلاین قیمت درب و پنجره دوجداره upvc</a></em>\n<br><em>امیدواریم که این مقاله برای علاقه مندان مفید واقع شده باشد.</em>\n    </div>', 'images/articles/مقایسه پنجره دوجداره لولایی با مدل کشویی از لحاظ عایق.webp', 'پنجره دوجداره کشویی بهتر است یا لولایی؟ پنجره فولکس واگنی و برتری اش نسبت به این دو', 'admin', '2022-02-05 10:35:38', 'published', 'پنجره دوجداره کشویی بهتر است یا لولایی؟ پنجره فولکس واگنی و برتری اش نسبت به این دو', 'پنجره دوجداره کشویی بهتر است یا لولایی؟مزایا و معایبشان چیست؟ میدانستید پنجره فولکس واگنی مزایای پنجره کشویی و لولایی را داردند', '2026-08-20 19:48:48', '2026-09-06 13:20:35', NULL, 1),
(20, 'پنجره ریلی یا کشویی برای چه مناطقی مناسب است؟', 'پنجره-ریلی-یا-کشویی-برای-چه-مناطقی-مناس', 'پنجره دوجداره کشویی آلومینیومی برای چه مناطقی مناسب است . از معایب پنجره دوجداره ریلی این است که عایق خوبی ندارد و برای همه جا مناسب نیست', 'این نوع پنجره به دلیل استفاده بهتر از تهویه طبیعی و مطلوب برای مناطقی با آب و هوای معتدل مناسب می‌باشد. بالعکس در مناطقی با سر و صدا و گرد و خاک زیاد این پنجره خواسته‌های شما را برآورده نمی‌سازد. این پنجره نسبت به پنجره‌های لولایی از 20 درصد عایق‌بندی کمتری برخوردار است. درصورت نیاز به حالت کشویی در نوع بازشو پیشنهاد می‌شود از یراق فولکس واگنی که دارای عایق‌بندی استانداردی می‌باشد استفاده کنید.<h2><b>پنجره دوجداره کشویی آلومینیومی در چه مناطقی کاربرد دارند؟</b></h2>پنجره‌های دوجداره کشویی برای مناطقی با آب و هوای معتدل بسیار مناسب هستند. استفاده از این نوع پنجره ها به دلیل آنکه به راحتی باز و بسته می‌شوند، هنگام استفاده از تهویه طبیعی و آب و هوای بیرون از ساختمان بسیار مطلوب است.\n\nتوجه داشته باشید، که استفاده از پنجره دوجداره کشویی برای استفاده در مناطق با سر و صدا، گرد و خاک زیاد، هوای خیلی گرم و یا هوای خیلی سرد، به هیچ عنوان مناسب نیست و نیازهای شما را برآورده نمی‌کند. پنجره‌های کشویی نسبت به پنجره‌های لولایی، حدود ۲۰ درصد عایق‌بندی کمتری دارد و به همین دلیل برای اینطور مناطق به هیچ عنوان توصیه نمی‌شود.\n\nاگر در این‌طور مناطق زندگی می‌کنید و مجبور به استفاده از پنجره دوجداره کشویی هستید، بهتر است، نوعی را بخرید که دارای یراق فولکس واگنی باشد. این نوع یراق ها دارای عایق‌بندی استانداردی هستند و نصب آن‌ها از هدر رفتن انرژی جلوگیری می‌کند.برای نصب درب و پنجره‌های دوجداره کشویی، ورودی تراس به اتاق خواب‌ها، ورودی تراس یا حیاط به آشپزخانه، ورودی حیاط به پذیرایی، ورودی ساختمان به سمت استخر و سایر مکان‌های اینچنینی مناسب است.\n\nدر آشپزخانه‌ها نیز استفاده از پنجره‌های کشویی به دلیل آسان بودن نحوه باز و بسته کردن‌شان، بسیار کاربردی است. اگر در بالای سینک ظرفشویی یا کابینت‌ها پنجره‌ای قرار داشته باشد، بهترین نوع پنجره برای این مکان، مدل کشویی است، زیرا این پنجره‌ها در هنگام باز و بسته شدن فضای اضافی اشغال نمی‌کنند.\n</div>\n  <div>', 'images/articles/پنجره ریلی یا کشویی برای چه مناطقی مناسب است.webp', 'پنجره ریلی یا کشویی برای چه مناطقی مناسب است؟', 'admin', '2021-01-20 08:30:56', 'published', 'پنجره ریلی یا کشویی برای چه مناطقی مناسب است؟', 'پنجره دوجداره کشویی آلومینیومی برای چه مناطقی مناسب است . از معایب پنجره دوجداره ریلی این است که عایق خوبی ندارد و برای همه جا مناسب نیست', '2026-08-20 19:48:48', '2026-09-06 13:20:35', NULL, 1),
(21, 'چرا بعضی از پنجره های UPVC بعد از مدتی دفرمه می شود؟', 'چرا-بعضی-از-پنجره-های-upvc-بعد-از-مدتی-دفرمه', 'از جمله مسائل بسیار مهم در تولید درب و پنجره های UpVC که بر استحکام و مقاومت پروفیل در برابر کج شدگی تاثیرگذار است گالوانیزه می باشد که می بایست به این…', 'از جمله مسائل بسیار مهم در تولید درب و پنجره های UpVC که بر استحکام و مقاومت پروفیل در برابر کج شدگی تاثیرگذار است گالوانیزه می باشد که می بایست به این موارد دقیت کرد.\n\n1- گالوانیزه میبایست با پیچ های استاندارد که با فواصل 15 سانتی متر از ابتدا و انتهای پروفیل و همچنین فاصله حداکثر 40 سانتی متر بین پیچ ها به پروفیل upvc متصل گردد.\n\n2- گالوانیزه میبایست به صورت کاملا یکپارچه در تمام طول سطح مقطع پروفیل استفاده گردد.سطح مقطع گالوانیزه می بایست متناسب با سطح مقطع پروفیل به صورت U شکل باشد.\n\n3- استفاده از گالوانیزه به ضخامت 1.25 میلی متر از طبقات اول تا پنجم در ابعاد و ارتفاع معمول بلا مانع می باشد و از طبقات 6 تا 25 با توجه به ابعاد و ارتفاع پنجره از گالوانیزه به ضخامت حداقل 1.5 میلی متر باید استفاده گردد.<h3>رگلاژ و رفع گیر و ایراد پنجره دوجداره در هنگام باز و بسته شدن</h3>گاهی اوقات پنجره‌های دوجداره در هنگام باز و بسته شدن گیر دارد، گاهی اوقات به سختی باز و بسته می‌شود و گاهی اوقات نیز آن‌قدر سفت و سخت است که اصلا نمی‌توان آن‌ها را باز و بسته کرد. بعضی وقت‌ها هم زمانی که پنجره را باز می‌کنیم، باز نمی‌ماند و خود به خود بسته می‌شود. این دسته از پنجره‌ها نیاز به رگلاژ و رفع گیر دارند. برای آنکه گیر آن‌ها رفع شود.<h3>اندازه‌گیری محل نصب پنجره دوجداره UPVC</h3>ساخت درب و پنجره دوجداره UPVC با دستگاه‌ها و ماشین آلات پیشرفته انجام می‌شود. برای آنکه این دستگاه‌ها عملکرد صحیحی داشته باشند، باید اطلاعات ورودی دقیقی دریافت کنند. به همین دلیل اندازه‌گیری محل نصب پنجره دوجداره، مرحله مهمی در روند تولید پنجره به حساب می‌آید.\n\nاندازه‌گیری دقیق و بدون اشتباه، اولین و مهم‌ترین مرحله در تولید پنجره دوجداره است. بنابراین برای اندازه‌گیری ابعاد پنجره دوجداره، لازم است که از مترهای دقیق لیزری استفاده شود و کسی که اندازه‌گیری را انجام می‌دهد، باید در استفاده از این مترها و نحوه اندازه‌گیری دقیق مهارت کافی را داشته باشد. مهارت کافی در اندازه‌گیر دقیق، باعث تولید محصول با کیفیت‌تر خواهد شد.<h3>اصلاح درزبندی و عایق بندی پنجره دوجداره</h3>درزبندی و عایق بندی پنجره های دوجداره بسیار مهم است. اگر درزبندی و عایق بندی پنجره‌ها درست نباشد یا با مرور زمان خراب شده باشد،‌ کارآیی اصلی پنجره از بین می‌رود و پنجره دوجداره،‌ دیگر فرقی با پنجره های قدیمی نخواهد داشت. بنابراین لازم است، که هر چند وقت یک بار درزبندی و عایق بندی پنجره های دوجداره UPVC را کنترل کنید و در صورتی که اشکالی داشتند،‌ آن‌ها را به کمک یک متخصص تعمیر کنید.\n    </div>', 'images/articles/چرا بعضی از پنجره های UPVC بعد از مدتی دفرمه می شود.webp', 'چرا بعضی از پنجره های UPVC بعد از مدتی دفرمه می شود؟', 'admin', '2021-07-16 12:33:51', 'published', 'چرا بعضی از پنجره های UPVC بعد از مدتی دفرمه می شود؟', 'از جمله مسائل بسیار مهم در تولید درب و پنجره های UpVC که بر استحکام و مقاومت پروفیل در برابر کج شدگی تاثیرگذار است گالوانیزه می باشد که می بایست به این…', '2026-08-20 19:48:48', '2026-09-06 13:20:35', NULL, 1),
(22, 'چطور توری پلیسه پنجره دوجداره را تمیز کنیم؟', 'چطور-توری-پلیسه-پنجره-دوجداره-را-تمیز-ک', 'چگونه توری پلیسه پنجره را تمیز کنیم؟ توری پنجره محل عبور جریان هوایی است که با خود آلودگی هایی همراه دارد. گردو غبار موجود در جریان هوا، بر روی توری می…', '<h2>چگونه توری پلیسه پنجره را تمیز کنیم؟</h2>توری پنجره محل عبور جریان هوایی است که با خود آلودگی هایی همراه دارد.گردو غبار موجود در جریان هوا، بر روی توری می نشیند و نظافت و شستشو را امری اجتناب ناپذیر می کند. اما برای شستشو توری پلیسه پنجره چه کار باید بکنیم؟توری پلیسه از نظر متحرک بودن فریم داخلی به دو دسته تقسیم می شوند که در نحوه پاکیزگی آنها تاثیرگذار است:<h2>شستشوی توری پلیسه ساده یا تک فریم</h2>در این مدل توری پنجره، نمیتوان توری باز شونده از فریم را بیرون آورد. زیرا توری به چارچوب قاب ثابت دور پیچ شده و آن را از چارچوب نمیتوان خارج کرد. در حالتی که نیاز به جابجایی توری پلیسه ساده دارید، پیچ هایی را که توری را به قاب پنجره متصل و ثابت کرده است را باید باز کنیم.برای نظافت اول باید از پارچه ای خیس برای پاک کردن گردوغبار استفاده کنیم. بعد با استفاده از اسپری چند منظوره و اسپری آب چربی باقیمانده بر روی توری را پاک کنیم. فشار اسپری منافذ و سوراخ های توری را تمیز می کند. برای راحت شدن نظافت، در دو حالت باز و بسته این عمل را انجام دهید.<h4>شستشوی توری پلیسه دبل فریم</h4>از مهم ترین خصوصیات توری دبل فریم، نظافت آسان با جابجا کردن توری است. چارچوب قاب دور این نوع توری از دو فریم جدا ساخت شده است که فریم اول به پنجره پیچ می شود اما فریم دوم با فشار در فریم اول قرار می گیرد. هنگامی که می خواهیم برای شستشوی توری دبل فریم اقدام کنیم، کافیست توری را جمع کنیم. سپس فریم دوم ( تنها در پروفیل های ارتفاعی استفاده شده است) را از چارچوب ثابت قاب دور جدا می کنیم و خارج می کنیم. برای شستشو نیز کافیست از مواد شوینده ملایم و فشار آب استفاده کنید.هنگام خارج کردن و یا قرار دادن توری در چارچوب، دقت کنید نخ توری آسیب نبیند.در توری های دیگر مانند توری ثابت، توری رولینگ و توری لولایی نیز می توان از شستشوی ساده استفاده کرد. اما اگر در نظافت توری موفق نبودید، می توانید از فرچه های شستشوی بطری و یا مسواک استفاده کنید.\n    </div>', 'images/articles/چطور توری پلیسه پنجره دوجداره را تمیز کنیم.webp', 'چطور توری پلیسه پنجره دوجداره را تمیز کنیم؟', 'admin', '2020-12-13 07:16:49', 'published', 'چطور توری پلیسه پنجره دوجداره را تمیز کنیم؟', 'چگونه توری پلیسه پنجره را تمیز کنیم؟ توری پنجره محل عبور جریان هوایی است که با خود آلودگی هایی همراه دارد. گردو غبار موجود در جریان هوا، بر روی توری می…', '2026-08-20 19:48:48', '2026-09-06 13:20:35', NULL, 1),
(23, 'چگونه قاب پنجره یو پی وی سی را دوباره سفید و براق کرد؟', 'چگونه-قاب-پنجره-یو-پی-وی-سی-را-دوباره-سف', 'برای زد شدن پنجره یو پی وی سی و تمیز کردن شیشه های دو جداره چه کار کنیم؟از بین بردن لکه روی پروفیل ها upvc و نظافت قاب های پنجره چگونه است؟', 'قاب پنجره با گذشت زمان دچار کثیفی شده و آن تمیزی که در زمان نصب داشته را قطعاً ندارد. برای تمیز کردن<strong> پنجره یو پی وی سی </strong>باید ابتدا از قاب آن شروع کرد. برای تمیز کردن قاب‌ باید مراحل را طبق برنامه زیر انجام داد:<ul><li>گردگیری اولین قدم برای داشتن یک پنجره تمیز</li></ul>برای تمیز کردن قاب ابتدا پنجره را تا جایی که ممکن است باز کرده و با یک دستمال میکروفایبر، همه کثیفی، گرد و غبار و خاک و.. را از اطراف و گوشه کنار قاب پاک کنید<ul><li>شستن چهارچوب پنجره‌ یو پی وی سی</li></ul>در مرحله‌ی دوم قاب پنجره را با<strong>آب گرم</strong>بشویید. یک سطل را با آب گرم پر کنید. سپس یک پارچه نخی نرم را داخل آب فرو کرده و به آرامی سطح داخل و خارج قاب پنجره را به طور کامل تمیز کنید. بعد از تمیزکردن قاب پنجره، آن را خشک کنید.<div>برخی از افراد از بخارشو برای شستن پنجره استفاده می‌کنند تا با بخار داغ آلودگی‌ها را کاملاً پاک کنند. استفاده از بخارشو بسیار خوب و مناسب بوده اما امکان دارد، تیغه و یا برس مخصوص بخارشو که برای شستشوی قسمت‌های کوچک و یا ریز طراحی شده، زبر باشد و باعث ایجاد خراش بر روی چهارچوب پنجره یو پی وی سی گردد.\n\nبنابراین توصیه می‌شود که از یک پارچه‌ی نخی سفید رنگ و نرم استفاده کنید. علتی که به رنگ سفید پارچه اشاره می‌شود این است که امکان دارد پارچه خود نیز به قاب پنجره یو پی وی سی رنگ بدهد و پاک کردن لکه‌های رنگی از روی قاب کار ساده‌ای نیست.\n\nبنابراین از پارچه‌های نخی نرم و سفید استفاده کنید که هیچ رنگی به قاب نداده و در عین حال باعث ایجاد خراش بر روی قاب هم نمی‌شوند.برای از بین بردن آلودگی‌ها از قاب پنجره یو پی وی سی، از پارچه‌های نرم و سفید کتانی استفاده کنید. علتی که رنگ سفید پارچه اشاره می‌ شود این است که امکان دارد پارچه خود نیز به قاب پنجره یو پی وی سی رنگ بدهد و پاک کردن لکه‌های رنگی از روی قاب کار راحت و ساده‌ای نیست.<ul><li>استفاده از محلول آب و صابون برای قاب‌<strong> پنجره یو پی وی سی </strong></li></ul>آب گرم و صابون یکی از موثرترین روش‌ها برای تمیز کردن است و گاهی اوقات، بهترین نتیجه را هم می‌دهد. شما می‌توانید یک محلول شستشو با آب گرم و صابون بسازید و سپس با کمک یک اسفنج نرم و تمیز و یا یک<strong>دستمال میکروفایبر</strong>، پنجره‌های خود را بشویید. یادتان باشد از اسکاچ‌های زبر و سخت برای شستشو استفاده نکنید. چون سطوح زبر اسکاچ‌ها باعث ایجاد خراش بر روی روکش‌های قاب پنجره‌ها می‌شود و حتی آن را از بین نیز می‌برد.\n\nپس از شستشو با محلول آب و صابون، قاب پنجره را با یک پارچه‌ی نمدار بدون پرز و باکیفیت همچون دستمال‌های میکروفایبر خشک کنید. نکته‌ای که باید در ادامه به آن اشاره شود این است که هرگز از مواد شوینده قوی همچون وایتکس برای تمیز کردن<strong> پنجره upvc </strong>استفاه نکنید.با استفاده از محلول بی‌خطر آب و صابون پنجره و قاب‌های یو پی وی سی را به صورت منظم تمیز کرده و رنگ پنجره‌های UPVC را نیز حفظ کنید.<h3><strong>چگونه می‌توان شیشه‌پنجره یو پی وی سی را تمیز و براق کرد؟</strong></h3>پس از تمیز و خشک کردن قاب پنجره، نوبت به شیشه‌های دوجداره است. برای تمیز و براق کردن شیشه‌های دوجداره بهتر است که از ترکیب آب و سرکه استفاده کنید. ترکیب آب و سرکه یک محلول تمیز کننده طبیعی بوده و آسیبی به بدنتان و در عین حال به وسائل شما همچون پنجره‌های یو پی وی سی نمی‌زند. پس دو فنجان آب را با یک چهارم فنجان سرکه مخلوط کرده و برای تمیز کردن شیشه‌ها از آن استفاده کنید.\n    </div>\n    <br>', 'images/articles/چگونه قاب پنجره یو پی وی سی را دوباره سفید و براق.webp', 'چگونه قاب پنجره یو پی وی سی را دوباره سفید و براق کرد؟', 'admin', '2020-08-16 12:03:39', 'published', 'چگونه قاب پنجره یو پی وی سی را دوباره سفید و براق کرد؟', 'برای زد شدن پنجره یو پی وی سی و تمیز کردن شیشه های دو جداره چه کار کنیم؟از بین بردن لکه روی پروفیل ها upvc و نظافت قاب های پنجره چگونه است؟', '2026-08-20 19:48:48', '2026-09-06 13:20:35', NULL, 1);
