INSERT INTO `page_blocks` (`id`, `page_id`, `key`, `type`, `label`, `value`, `sort_order`, `created_at`, `updated_at`) VALUES
(1, 1, 'hero_title', 'html', 'عنوان هیرو', 'تولید و نصب پنجره دوجداره UPVC<br>با کیفیت و قیمت مناسب', 0, '2026-08-20 13:19:04', '2026-08-20 13:19:04'),
(2, 1, 'hero_text', 'textarea', 'متن هیرو', 'پیشرو در تولید و نصب پنجره و درب دوجداره UPVC با استانداردهای اروپایی، قیمت شفاف و مشاوره رایگان.', 1, '2026-08-20 13:19:04', '2026-08-20 13:19:04'),
(3, 1, 'hero_stat_1_number', 'text', 'آمار ۱', '+۱۵', 2, '2026-08-20 13:19:04', '2026-08-20 13:19:04'),
(4, 1, 'hero_stat_1_label', 'text', 'برچسب آمار ۱', 'سال تجربه در تولید و نصب', 3, '2026-08-20 13:19:04', '2026-08-20 13:19:04'),
(5, 1, 'hero_stat_2_number', 'text', 'آمار ۲', '+۵۰۰', 4, '2026-08-20 13:19:04', '2026-08-20 13:19:04'),
(6, 1, 'hero_stat_2_label', 'text', 'برچسب آمار ۲', 'پروژه موفق در سراسر کشور', 5, '2026-08-20 13:19:04', '2026-08-20 13:19:04'),
(7, 1, 'about_title', 'text', 'عنوان درباره', 'ALWIN', 6, '2026-08-20 13:19:04', '2026-08-20 13:19:04'),
(8, 1, 'about_text', 'textarea', 'متن درباره', 'با بیش از ۱۵ سال تجربه در تولید، نصب و خدمات پس از فروش پنجره و درب UPVC، ALWIN همراه شماست از انتخاب مدل تا نصب نهایی. پروفیل‌های معتبر، شیشه‌های باکیفیت و تیم نصب حرفه‌ای — همه در یک آدرس.', 7, '2026-08-20 13:19:04', '2026-08-20 13:19:04'),
(9, 1, 'about_button', 'text', 'دکمه درباره', 'بیشتر بدانید', 8, '2026-08-20 13:19:04', '2026-08-20 13:19:04'),
(10, 1, 'clients_title', 'text', 'عنوان مشتریان', 'مشتریان ما: همراهی با برندهای معتبر و صدها خانواده راضی در سراسر ایران', 9, '2026-08-20 13:19:04', '2026-08-20 13:19:04'),
(11, 1, 'clients_text', 'textarea', 'متن مشتریان', 'کیفیت محصول و خدمات ALWIN مورد اعتماد سازندگان، معماران و مالکین واحدهای مسکونی و تجاری است. ما به کیفیت متعهد هستیم و آن را در هر پروژه ثابت می‌کنیم.', 10, '2026-08-20 13:19:04', '2026-08-20 13:19:04'),
(12, 1, 'cta_title', 'text', 'عنوان بنر محاسبه قیمت', 'قیمت پنجره‌تان را همین حالا ببینید', 11, '2026-08-20 13:19:04', '2026-09-14 17:59:17'),
(13, 1, 'work_title', 'text', 'عنوان پروژه‌های خانه', 'پروژه‌های اجرا شده', 12, '2026-08-20 13:19:04', '2026-08-20 13:19:04'),
(14, 1, 'work_text', 'textarea', 'متن پروژه‌های خانه', 'نمونه‌ای از پروژه‌های نصب پنجره و درب UPVC در تهران و شهرهای اطراف', 13, '2026-08-20 13:19:04', '2026-08-20 13:19:04'),
(15, 1, 'products_title', 'text', 'عنوان محصولات خانه', 'محصولات', 14, '2026-08-20 13:19:04', '2026-08-20 13:19:04'),
(16, 1, 'principles_title', 'html', 'اصول', 'کیفیت، دقت و <br> قیمت منصفانه — <span>سه اصل</span> <span>ALWIN</span> در <span>هر پروژه</span>', 15, '2026-08-20 13:19:04', '2026-09-14 17:59:17'),
(17, 2, 'legal_name', 'text', 'نام حقوقی', 'شرکت بهینه گستر نمای آفتاب', 0, '2026-08-20 13:19:04', '2026-08-20 13:19:04'),
(18, 2, 'hero_title', 'text', 'عنوان', 'از ثبت ۱۳۹۲ تا تولید حرفه‌ای در و پنجره', 1, '2026-08-20 13:19:04', '2026-08-20 13:19:04'),
(19, 2, 'hero_lead', 'textarea', 'متن مقدمه', 'آلوین با مدرن‌ترین ماشین‌آلات روز دنیا، تولید در و پنجره‌های UPVC، آلومینیوم و انواع توری را آغاز کرد — و مسیر کیفیت را با نمایندگی برندهای معتبر ادامه داد.', 2, '2026-08-20 13:19:04', '2026-08-20 13:19:04'),
(20, 2, 'cta_contact', 'text', 'دکمه تماس', 'تماس با آلوین', 3, '2026-08-20 13:19:04', '2026-08-20 13:19:04'),
(21, 2, 'cta_story', 'text', 'دکمه داستان', 'داستان ما', 4, '2026-08-20 13:19:04', '2026-08-20 13:19:04'),
(22, 2, 'story_title', 'text', 'عنوان داستان', 'بهینه گستر نمای آفتاب؛ نام تجاری آلوین', 5, '2026-08-20 13:19:04', '2026-08-20 13:19:04'),
(23, 2, 'story_html', 'html', 'متن داستان', '<p>شرکت <strong>بهینه گستر نمای آفتاب</strong> با نام تجاری <strong>آلوین (ALWIN)</strong> در سال ۱۳۹۲ با شماره ثبت <strong>۴۴۶۴۱۹</strong> ثبت شد و با بهره‌گیری از مدرن‌ترین ماشین‌آلات روز دنیا، فعالیت خود را در زمینه تولید <strong>در و پنجره‌های UPVC، آلومینیوم و انواع توری</strong> آغاز نمود.</p><p>این مجموعه در راستای توسعه و پیشبرد اهداف خود موفق به اخذ نمایندگی از شرکت <strong>وین‌تک</strong> با درجه کیفی <strong>A</strong> و همچنین اخذ نمایندگی از شرکت <strong>ویستابست</strong> از سال ۹۹ گردیده است.</p><p>امید است با استعانت و یاری از پروردگار یکتا و تأییدات الهی، با ساختار کارگروهی، تکیه بر سرمایه‌های اجتماعی، بهره‌گیری از تجربه مدیران و پیاده‌سازی استراتژی‌ها در عمل، بتوانیم بیش از پیش رضایت مشتریان خود را فراهم نماییم.</p>', 6, '2026-08-20 13:19:04', '2026-09-14 18:07:26'),
(24, 5, 'hero_title', 'text', 'عنوان', 'مشاوره مستقیم با تیم تولید و نصب', 0, '2026-08-20 13:19:04', '2026-08-20 13:19:04'),
(25, 5, 'hero_lead', 'textarea', 'متن مقدمه', 'برای سفارش، بازدید فنی یا دریافت قیمت شفاف، از خط ویژه یا فرم زیر با آلوین در ارتباط باشید.', 1, '2026-08-20 13:19:04', '2026-08-20 13:19:04'),
(26, 5, 'cta_call', 'text', 'دکمه تماس', 'تماس با خط ویژه', 2, '2026-08-20 13:19:04', '2026-08-20 13:19:04'),
(27, 5, 'cta_form', 'text', 'دکمه فرم', 'ارسال پیام', 3, '2026-08-20 13:19:04', '2026-08-20 13:19:04'),
(28, 5, 'office_title', 'text', 'عنوان دفتر', 'آدرس مراجعه حضوری', 4, '2026-08-20 13:19:04', '2026-08-20 13:19:04'),
(29, 3, 'hero_title', 'text', 'عنوان صفحه محصولات', 'محصولات آلوین', 0, '2026-08-20 13:19:04', '2026-08-20 13:19:04'),
(30, 3, 'hero_lead', 'textarea', 'توضیح محصولات', 'تمام مدل‌های پنجره و درب دوجداره UPVC و توری‌های پنجره را در یک‌جا ببینید — از پنجره‌های لولایی، کشویی و فرانسوی تا توری‌های پلیسه‌ای و رولینگ. برای هر مدل جزئیات را ببینید و استعلام بگیرید.', 1, '2026-08-20 13:19:04', '2026-08-20 13:19:04'),
(31, 4, 'hero_title', 'text', 'عنوان پروژه‌ها', 'پروژه‌های اجرایی آلوین', 0, '2026-08-20 13:19:04', '2026-08-20 13:19:04'),
(32, 4, 'hero_lead', 'textarea', 'توضیح پروژه‌ها', 'نمونه‌ای از پروژه‌های نصب پنجره و درب UPVC، نمای کرتین وال، جام بالکن و شیشه دوجداره — اجرا شده با دقت مهندسی و استاندارد اروپایی در تهران و شهرهای اطراف.', 1, '2026-08-20 13:19:04', '2026-08-20 13:19:04'),
(33, 1, 'cta_kicker', 'text', 'برچسب بنر محاسبه قیمت', 'برآورد آنلاین و رایگان', 12, '2026-09-14 17:59:17', '2026-09-14 18:09:28'),
(34, 1, 'cta_hint', 'textarea', 'توضیح بنر محاسبه قیمت', 'ابعاد را وارد کنید؛ نتیجه را در لحظه ببینید', 13, '2026-09-14 17:59:17', '2026-09-14 18:11:23'),
(35, 1, 'work_all_button', 'text', 'دکمه همه پروژه‌ها', 'مشاهده همه پروژه‌ها', 16, '2026-09-14 17:59:17', '2026-09-14 17:59:17'),
(36, 1, 'clients_marquee_title', 'text', 'عنوان نوار مشتریان', 'برخی از مشتریان ما', 19, '2026-09-14 17:59:17', '2026-09-14 17:59:17'),
(37, 1, 'hero_video_name', 'text', 'نام ویدیو معرفی', 'ویدیو معرفی آلوین پنجره', 20, '2026-09-14 17:59:17', '2026-09-14 17:59:17'),
(38, 1, 'intro_pause_label', 'text', 'برچسب توقف ویدیو', 'توقف ویدیو', 21, '2026-09-14 17:59:17', '2026-09-14 17:59:17'),
(39, 1, 'intro_play_label', 'text', 'برچسب پخش ویدیو', 'پخش ویدیو', 22, '2026-09-14 17:59:17', '2026-09-14 17:59:17'),
(40, 2, 'fact_1_value', 'text', 'آمار ۱', '۱۳۹۲', 7, '2026-09-14 17:59:17', '2026-09-14 17:59:17');
