(48, 2, 'chip_1_text', 'text', 'کارت ۱ متن', 'در و پنجره UPVC، آلومینیوم و انواع توری با ماشین‌آلات مدرن', 15, '2026-09-14 17:59:17', '2026-09-14 17:59:17'),
