(50, 2, 'chip_2_text', 'text', 'کارت ۲ متن', 'اخذ نمایندگی شرکت وین‌تک با بالاترین درجه کیفی', 17, '2026-09-14 17:59:17', '2026-09-14 17:59:17'),
