(52, 2, 'chip_3_text', 'text', 'کارت ۳ متن', 'نمایندگی رسمی ویستابست در غرب تهران و کرج', 19, '2026-09-14 17:59:17', '2026-09-14 17:59:17'),
(53, 2, 'chip_4_title', 'text', 'کارت ۴ عنوان', 'ضمانت و خدمات', 20, '2026-09-14 17:59:17', '2026-09-14 17:59:17'),
(54, 2, 'chip_4_text', 'text', 'کارت ۴ متن', 'محصولات همراه با گارانتی و خدمات پس از فروش', 21, '2026-09-14 17:59:17', '2026-09-14 17:59:17'),
(55, 2, 'path_eyebrow', 'text', 'برچسب مسیر رشد', 'مسیر رشد', 22, '2026-09-14 17:59:17', '2026-09-14 17:59:17'),
(56, 2, 'path_title', 'text', 'عنوان مسیر رشد', 'از تأسیس تا نمایندگی‌های رسمی', 23, '2026-09-14 17:59:17', '2026-09-14 17:59:17'),
(57, 2, 'path_lead', 'textarea', 'متن مسیر رشد', 'نقاط کلیدی در شکل‌گیری هویت صنعتی آلوین، بر اساس مسیر واقعی شرکت.', 24, '2026-09-14 17:59:17', '2026-09-14 17:59:17'),
(58, 2, 'path_1_year', 'text', 'مسیر ۱ سال', '۱۳۹۲', 25, '2026-09-14 17:59:17', '2026-09-14 17:59:17'),
(59, 2, 'path_1_title', 'text', 'مسیر ۱ عنوان', 'ثبت شرکت و آغاز تولید', 26, '2026-09-14 17:59:17', '2026-09-14 17:59:17'),
(60, 2, 'path_1_text', 'textarea', 'مسیر ۱ متن', 'ثبت شرکت بهینه گستر نمای آفتاب با شماره ۴۴۶۴۱۹ و شروع تولید در و پنجره UPVC، آلومینیوم و توری.', 27, '2026-09-14 17:59:17', '2026-09-14 17:59:17'),
(61, 2, 'path_2_year', 'text', 'مسیر ۲ سال', 'وین‌تک', 28, '2026-09-14 17:59:17', '2026-09-14 17:59:17'),
(62, 2, 'path_2_title', 'text', 'مسیر ۲ عنوان', 'نمایندگی درجه کیفی A', 29, '2026-09-14 17:59:17', '2026-09-14 17:59:17'),
(63, 2, 'path_2_text', 'textarea', 'مسیر ۲ متن', 'اخذ نمایندگی شرکت وین‌تک با درجه کیفی A در مسیر توسعه و ارتقای استاندارد تولید.', 30, '2026-09-14 17:59:17', '2026-09-14 17:59:17'),
(64, 2, 'path_3_year', 'text', 'مسیر ۳ سال', 'از سال ۹۹', 31, '2026-09-14 17:59:17', '2026-09-14 17:59:17'),
(65, 2, 'path_3_title', 'text', 'مسیر ۳ عنوان', 'نمایندگی ویستابست', 32, '2026-09-14 17:59:17', '2026-09-14 17:59:17'),
(66, 2, 'path_3_text', 'textarea', 'مسیر ۳ متن', 'اخذ نمایندگی ویستابست و سپس نمایندگی رسمی در غرب تهران و کرج، با ضمانت و خدمات پس از فروش.', 33, '2026-09-14 17:59:17', '2026-09-14 17:59:17'),
(67, 2, 'dealers_eyebrow', 'text', 'برچسب نمایندگی‌ها', 'شراکت‌های رسمی', 34, '2026-09-14 17:59:17', '2026-09-14 17:59:17'),
(68, 2, 'dealers_title', 'text', 'عنوان نمایندگی‌ها', 'نمایندگی برندهای معتبر پروفیل', 35, '2026-09-14 17:59:17', '2026-09-14 17:59:17'),
(69, 2, 'dealers_lead', 'textarea', 'متن نمایندگی‌ها', 'آلوین مسیر کیفیت را با نمایندگی برندهایی طی کرده که استاندارد ساخت و نصب را جدی می‌گیرند.', 36, '2026-09-14 17:59:17', '2026-09-14 17:59:17'),
(70, 2, 'dealer_1_tag', 'text', 'نمایندگی ۱ برچسب', 'نمایندگی', 37, '2026-09-14 17:59:17', '2026-09-14 17:59:17'),
(71, 2, 'dealer_1_name', 'text', 'نمایندگی ۱ نام', 'وین‌تک — درجه A', 38, '2026-09-14 17:59:17', '2026-09-14 17:59:17'),
(72, 2, 'dealer_1_text', 'textarea', 'نمایندگی ۱ متن', 'اخذ نمایندگی شرکت وین‌تک با درجه کیفی A، در راستای توسعه و پیشبرد اهداف تولیدی مجموعه.', 39, '2026-09-14 17:59:17', '2026-09-14 17:59:17'),
(73, 2, 'dealer_2_tag', 'text', 'نمایندگی ۲ برچسب', 'نمایندگی رسمی', 40, '2026-09-14 17:59:17', '2026-09-14 17:59:17'),
(74, 2, 'dealer_2_name', 'text', 'نمایندگی ۲ نام', 'ویستابست — غرب تهران و کرج', 41, '2026-09-14 17:59:17', '2026-09-14 17:59:17'),
(75, 2, 'dealer_2_text', 'textarea', 'نمایندگی ۲ متن', 'نمایندگی رسمی شرکت ویستابست در غرب تهران و کرج؛ محصولات مطابق استانداردهای فنی ویستابست، همراه با ضمانت و خدمات پس از فروش.', 42, '2026-09-14 17:59:17', '2026-09-14 17:59:17'),
(76, 2, 'vista_eyebrow', 'text', 'برچسب ویستابست', 'چرا ویستابست؟', 43, '2026-09-14 17:59:17', '2026-09-14 17:59:17'),
(77, 2, 'vista_title', 'text', 'عنوان ویستابست', 'کیفیت پروفیل‌ها و پنجره‌های ویستابست', 44, '2026-09-14 17:59:17', '2026-09-14 17:59:17'),
(78, 2, 'vista_intro', 'textarea', 'متن ویستابست', 'در راستای دیدگاه کیفیت‌محور شرکت ویستابست، حمایت از حقوق مصرف‌کنندگان و آشنایی تولیدکنندگان پنجره با استانداردهای ساخت و نصب، این شرکت دفترچه الزامات فنی ویستابست را منتشر نموده است.', 45, '2026-09-14 17:59:17', '2026-09-14 17:59:17'),
(79, 2, 'vista_points', 'textarea', 'نکات ویستابست (هر خط یک مورد)', 'بهره‌گیری از دانش فنی شرکت‌های معتبر بین‌المللی در تأمین مواد اولیه و استفاده از ماشین‌آلات مدرن.\nتولید پروفیل‌هایی با ماندگاری و کیفیت بالا در شرایط آب‌وهوایی مختلف ایران.\nنظارت واحد کنترل کیفیت بر فرآیند تولید و انجام آزمون‌های تخصصی در آزمایشگاه مجهز.\nتضمین کیفیت محصولات مطابق با استانداردهای ملی و بین‌المللی.', 46, '2026-09-14 17:59:17', '2026-09-14 17:59:17'),
(80, 2, 'warranty_eyebrow', 'text', 'برچسب گارانتی', 'تعهد پس از فروش', 47, '2026-09-14 17:59:17', '2026-09-14 17:59:17');
